579	fn print_row(stdout: &mut impl Write, line: &str, selected: bool, bg: &str, w: usize, row: u16) -> io::Result<()> {
580	    execute!(stdout, cursor::MoveTo(0, row))?;
581	    if selected {
582	        let colored = with_bg(line, bg);
583	        let vis = visible_width(line);
584	        let pad = w.saturating_sub(vis);
585	        write!(stdout, "\x1b[{bg}m{colored}{}\x1b[0m", " ".repeat(pad))?;
586	    } else {
587	        write!(stdout, "{line}")?;
588	        execute!(stdout, terminal::Clear(ClearType::UntilNewLine))?;
589	    }
590	    Ok(())
591	}
