593	fn draw_status(stdout: &mut impl Write, bar: &str, w: usize, h: usize) -> io::Result<()> {
594	    let display: String = bar.chars().take(w).collect();
595	    let padded = format!("{:<width$}", display, width = w);
596	    execute!(stdout, cursor::MoveTo(0, (h - 1) as u16))?;
597	    write!(stdout, "\x1b[7m{padded}\x1b[0m")
598	}
