                format!("~{}", &dir[home.len()..])
            } else { dir.clone() };
            let branch_part = if !branch.is_empty() {
                format!("  \x1b[{lb}m[{branch}]\x1b[0m", lb = th.label)
            } else { String::new() };
            lines.push(format!(
                "\x1b[{dm}m▸ repo  \x1b[0m\x1b[1;{lk}m{name}\x1b[0m  \x1b[{dm}m{short}\x1b[0m{branch_part}",
