166	
167	    let mut stdout = io::stdout();
168	    terminal::enable_raw_mode()?;
169	    execute!(stdout, EnterAlternateScreen, cursor::Hide)?;
170	
171	    let result = tui_loop(&mut stdout, &groups, query, ms);
172	
173	    execute!(stdout, LeaveAlternateScreen, cursor::Show)?;
174	    terminal::disable_raw_mode()?;
175	
176	    result
177	}
