179	/// The ingest pipeline prefixes user turns with `[User] ` so the embedded
180	/// body string distinguishes roles. The author column now carries that
181	/// information at the row level, so strip the inline tag from excerpts.
182	fn strip_user_label(s: &str) -> String {
183	    s.strip_prefix("[User] ")
184	        .or_else(|| s.strip_prefix("[User]"))
185	        .unwrap_or(s)
186	        .to_string()
187	}
