189	// ── Hit parsing ───────────────────────────────────────────────────────────────
190	
191	fn parse_hit(metadata_json: &str, bodies: &[String], sub_idx: u32) -> SearchHit {
192	    let sub_idx = sub_idx as usize;
193	    let meta: serde_json::Value = serde_json::from_str(metadata_json).unwrap_or_default();
194	    let source = meta["source"].as_str().unwrap_or("claude");
195	
196	    match source {
197	        "session" => {
198	            let name = meta["session_name"].as_str().unwrap_or("").to_string();
199	            let cwd  = meta["cwd"].as_str().unwrap_or("").to_string();
200	            SearchHit {
201	                kind: HitKind::Session,
202	                title: name,
203	                dir: short_path(&cwd),
204	                excerpt_lines: vec![],
205	                session_id: meta["session_id"].as_str().map(str::to_string),
206	                repo_dir: None,
207	                start_ts: None, hit_ts: None, branch: String::new(),
208	                agent: String::new(), backed_up: false, updated_at: String::new(), author: String::new(),
209	                remote: String::new(),
210	            }
211	        }
212	        "repo" => {
213	            let name = meta["repo_name"].as_str().unwrap_or("").to_string();
214	            let dir  = meta["repo_dir"].as_str().unwrap_or("").to_string();
215	            SearchHit {
216	                kind: HitKind::Repo,
217	                title: name,
218	                dir: short_path(&dir),
219	                excerpt_lines: vec![],
220	                session_id: None,
221	                repo_dir: Some(dir),
222	                start_ts: None, hit_ts: None, branch: String::new(),
223	                agent: String::new(), backed_up: false, updated_at: String::new(), author: String::new(),
224	                remote: String::new(),
225	            }
226	        }
227	        _ => {
228	            // "claude" — session log turn
229	            let name   = meta["session_name"].as_str().unwrap_or("").to_string();
230	            let project = meta["project"].as_str().unwrap_or("").to_string();
231	            let branch  = meta["branch"].as_str().unwrap_or("").to_string();
232	
233	            // Collect context: previous turn, matched turn, next turn.
234	            // bodies[0] is the header; bodies[N] for N>0 is a conversation turn.
235	            // Strip the "[User] " prefix the ingest pipeline bakes into every
236	            // user turn — the author column already shows who the user was,
237	            // so the inline label is redundant. "[Claude]" is kept because it
238	            // distinguishes assistant turns and has no column-level analog.
239	            let mut excerpt_lines: Vec<String> = Vec::new();
240	            if sub_idx > 1 {
241	                if let Some(prev) = bodies.get(sub_idx - 1) {
242	                    let t: String = strip_user_label(prev.trim()).chars().take(220).collect();
243	                    if !t.is_empty() { excerpt_lines.push(t); }
244	                }
245	            }
246	            if let Some(matched) = bodies.get(sub_idx) {
247	                let t: String = strip_user_label(matched.trim()).chars().take(400).collect();
248	                if !t.is_empty() { excerpt_lines.push(t); }
249	            }
250	            if sub_idx + 1 < bodies.len() {
251	                if let Some(next) = bodies.get(sub_idx + 1) {
252	                    let t: String = strip_user_label(next.trim()).chars().take(220).collect();
253	                    if !t.is_empty() { excerpt_lines.push(t); }
254	                }
255	            }
256	
257	            let hit_ts = if sub_idx > 0 {
258	                meta["turns"][sub_idx - 1]["timestamp"].as_str()
259	                    .filter(|s| !s.is_empty())
260	                    .map(str::to_string)
261	            } else {
262	                None
263	            };
264	
265	            SearchHit {
266	                kind: HitKind::Log,
267	                title: name,
268	                dir: short_path(&project),
269	                excerpt_lines,
270	                session_id: meta["session_id"].as_str().map(str::to_string),
271	                repo_dir: None,
272	                start_ts: hit_ts.clone(),
273	                hit_ts,
274	                branch,
275	                agent: String::new(), backed_up: false, updated_at: String::new(), author: String::new(),
276	                remote: String::new(),
277	            }
278	        }
279	    }
280	}
