359	// ── TUI ───────────────────────────────────────────────────────────────────────
360	
361	fn tui_loop(stdout: &mut impl Write, groups: &[Group], query: &str, ms: u128) -> Result<bool> {
362	    let mut sel    = 0usize;
363	    let mut scroll = 0usize;
364	    let mut quit_app = false;
365	
366	    loop {
367	        let (w, h) = terminal::size().unwrap_or((120, 40));
368	        let w = w as usize;
369	        let h = h as usize;
370	        let content_h = h.saturating_sub(2);
371	
372	        let sel_start = group_start_of(groups, sel);
373	        let sel_end   = sel_start + groups.get(sel).map_or(1, rows_for_group);
374	        if sel_start < scroll                { scroll = sel_start; }
375	        else if sel_end > scroll + content_h { scroll = sel_end.saturating_sub(content_h); }
376	
377	        draw(stdout, groups, query, ms, sel, scroll, w, h)?;
378	
379	        match event::read()? {
380	            Event::Key(k) => match k.code {
381	                KeyCode::Char('q') => { quit_app = true; break; }
382	                KeyCode::Esc => break,
383	                KeyCode::Char('c') if k.modifiers.contains(crossterm::event::KeyModifiers::CONTROL) => {
384	                    execute!(stdout, LeaveAlternateScreen, cursor::Show).ok();
385	                    terminal::disable_raw_mode().ok();
386	                    std::process::exit(0);
387	                }
388	                KeyCode::Up   | KeyCode::Char('k') => { if sel > 0 { sel -= 1; } }
389	                KeyCode::Down | KeyCode::Char('j') => { if sel + 1 < groups.len() { sel += 1; } }
390	                KeyCode::Char('g') => { sel = 0; scroll = 0; }
391	                KeyCode::Char('G') => { sel = groups.len().saturating_sub(1); }
392	                KeyCode::Char(' ') | KeyCode::Right | KeyCode::Enter => {
393	                    if let Some(group) = groups.get(sel) {
394	                        execute!(stdout, LeaveAlternateScreen, cursor::Show).ok();
395	                        terminal::disable_raw_mode().ok();
396	
397	                        let nested_quit = match group.kind {
398	                            HitKind::Log | HitKind::Session => {
399	                                if let Some(id) = &group.session_id {
400	                                    let ts = group.rows.first().and_then(|r| r.start_ts.as_deref());
401	                                    super::show::run_at(id, ts).unwrap_or(false)
402	                                } else { false }
403	                            }
404	                            HitKind::Repo => {
405	                                if let Some(dir) = &group.repo_dir {
406	                                    let _ = super::status::run_for_dir(dir);
407	                                }
408	                                false
409	                            }
410	                        };
411	
412	                        if nested_quit { quit_app = true; break; }
413	
414	                        terminal::enable_raw_mode().ok();
415	                        execute!(stdout, EnterAlternateScreen, cursor::Hide).ok();
416	                        execute!(stdout, terminal::Clear(ClearType::All)).ok();
417	                    }
418	                }
419	                _ => {}
420	            },
421	            Event::Resize(_, _) => {
422	                execute!(stdout, terminal::Clear(ClearType::All)).ok();
423	            }
424	            _ => {}
425	        }
426	    }
427	
428	    Ok(quit_app)
429	}
430	
431	fn rows_for_group(g: &Group) -> usize {
432	    1 + g.rows.iter().map(|r| r.lines.len().max(1)).sum::<usize>() + 1 // +1 for blank separator
433	}
434	
435	fn group_start_of(groups: &[Group], idx: usize) -> usize {
436	    groups[..idx.min(groups.len())].iter().map(rows_for_group).sum()
437	}
