439	// ── Rendering ─────────────────────────────────────────────────────────────────
440	
441	fn draw(
442	    stdout: &mut impl Write,
443	    groups: &[Group],
444	    query:  &str,
445	    ms:     u128,
446	    sel:    usize,
447	    scroll: usize,
448	    w:      usize,
449	    h:      usize,
450	) -> io::Result<()> {
451	    use crossterm::queue;
452	    let t = crate::theme::get();
453	    let sel_bg = t.sel_bg;
454	    const TS_W: usize = 12; // fixed width of the timestamp column in excerpt rows
455	
456	    let content_h = h.saturating_sub(2);
457	    let mut buf: Vec<u8> = Vec::with_capacity((w + 60) * (h + 2));
458	
459	    // Title bar
460	    queue!(buf, cursor::MoveTo(0, 0), terminal::Clear(ClearType::UntilNewLine))?;
461	    let hdr = format!("  search: \"{}\"  {} result(s)  {}ms", query, groups.len(), ms);
462	    write!(buf, "\x1b[1m{}\x1b[0m", hdr.chars().take(w).collect::<String>())?;
463	
464	    // Pre-compute column widths across all groups for tabular alignment.
465	    let name_w   = groups.iter().map(|g| g.title.trim().chars().count()).max().unwrap_or(0).min(45);
466	    let agent_w  = groups.iter().map(|g| g.agent.chars().count()).max().unwrap_or(0);
467	    let author_w = groups.iter().map(|g| g.author.chars().count()).max().unwrap_or(0);
468	    let branch_w = groups.iter().map(|g| g.branch.chars().count()).max().unwrap_or(0).min(30);
469	
470	    let mut screen_row = 1usize; // next terminal row to write (row 0 is title bar)
471	    let mut abs_row    = 0usize; // absolute content row (before scroll is applied)
472	
473	    for (gi, group) in groups.iter().enumerate() {
474	        if screen_row > content_h { break; }
475	        let selected = gi == sel;
476	
477	        // ── Session header ────────────────────────────────────────────────
478	        if abs_row >= scroll && screen_row <= content_h {
479	            let age     = age_secs_hit(&group.updated_at);
480	            let dot_col = match age {
481	                a if a < 900   => t.fresh,
482	                a if a < 3_600 => t.moderate,
483	                _              => t.text_dim,
484	            };
485	            let (name_col, meta_col, dot_char) = if group.backed_up {
486	                (t.backed_name, t.backed_meta, "*")
487	            } else {
488	                (t.unbacked_name, t.unbacked_meta, "·")
489	            };
490	
491	            let name: String = group.title.trim().chars().take(name_w).collect();
492	            let name_padded  = format!("{name:<name_w$}");
493	            let mut line = format!(
494	                "\x1b[{dot_col}m{dot_char}\x1b[0m \x1b[{name_col}m{name_padded}\x1b[0m  \x1b[{dm}m{}\x1b[0m",
495	                group.dir, dm = t.text_dim,
496	            );
497	
498	            if branch_w > 0 {
499	                let branch_col = if group.backed_up { t.link } else { t.stale };
500	                let b: String = group.branch.chars().take(branch_w).collect();
501	                let pad = " ".repeat(branch_w - b.chars().count());
502	                line.push_str(&format!("  \x1b[{branch_col}m{b}{pad}\x1b[0m"));
503	            }
504	
505	            if author_w > 0 {
506	                let a: String = group.author.chars().take(author_w).collect();
507	                let pad = " ".repeat(author_w - a.chars().count());
508	                let col = super::author_color(&group.author);
509	                line.push_str(&format!("  \x1b[38;5;{col}m{a}\x1b[0m{pad}"));
510	            }
511	
512	            if agent_w > 0 {
513	                let a: String = group.agent.chars().take(agent_w).collect();
514	                let pad = " ".repeat(agent_w - a.chars().count());
515	                if group.backed_up {
516	                    let col = agent_color(&group.agent);
517	                    line.push_str(&format!("  \x1b[38;5;{col}m{a}{pad}\x1b[0m"));
518	                } else {
519	                    line.push_str(&format!("  \x1b[{st}m{a}{pad}\x1b[0m", st = t.stale));
520	                }
521	            }
522	
523	            if let Some(sid) = &group.session_id {
524	                let id_short: String = sid.chars().take(8).collect();
525	                let ts = rel_time_hit(&group.updated_at);
526	                line.push_str(&format!("  \x1b[{meta_col}m{id_short}  {ts}\x1b[0m"));
527	            } else if matches!(group.kind, HitKind::Repo) {
528	                line.push_str(&format!("  \x1b[{meta_col}mrepo\x1b[0m"));
529	            }
530	
531	            render_row(&mut buf, &line, selected, sel_bg, screen_row, w)?;
532	            screen_row += 1;
533	        }
534	        abs_row += 1;
535	
536	        // ── Excerpt rows ──────────────────────────────────────────────────
537	        for row in &group.rows {
538	            let ts_str = row.hit_ts.as_deref().map(rel_time_hit).unwrap_or_default();
539	            let n_lines = row.lines.len().max(1);
540	            let excerpt_indent = " ".repeat(2 + TS_W + 2);
541	
542	            for li in 0..n_lines {
543	                if abs_row >= scroll && screen_row <= content_h {
544	                    let text = row.lines.get(li).map(String::as_str).unwrap_or("");
545	                    let avail = w.saturating_sub(2 + TS_W + 2);
546	                    let text_t: String = text.chars().take(avail).collect();
547	
548	                    let exc_line = if li == 0 {
549	                        let ts_padded = format!("{ts_str:>TS_W$}");
550	                        format!(
551	                            "  \x1b[{dm}m{ts_padded}\x1b[0m  \x1b[{sc}m{text_t}\x1b[0m",
552	                            dm = t.text_dim, sc = t.text_secondary,
553	                        )
554	                    } else {
555	                        format!("{excerpt_indent}\x1b[{sc}m{text_t}\x1b[0m", sc = t.text_secondary)
556	                    };
557	
558	                    render_row(&mut buf, &exc_line, selected, sel_bg, screen_row, w)?;
559	                    screen_row += 1;
560	                }
561	                abs_row += 1;
562	            }
563	        }
564	
565	        // Blank separator row between groups
566	        if abs_row >= scroll && screen_row <= content_h {
567	            queue!(buf, cursor::MoveTo(0, screen_row as u16), terminal::Clear(ClearType::UntilNewLine))?;
568	            screen_row += 1;
569	        }
570	        abs_row += 1;
571	    }
572	
573	    // Clear any leftover rows below the results.
574	    while screen_row <= content_h {
575	        queue!(buf, cursor::MoveTo(0, screen_row as u16), terminal::Clear(ClearType::UntilNewLine))?;
576	        screen_row += 1;
577	    }
578	
579	    // Status bar
580	    let bar = "  ↑↓/jk: navigate   space/→: open   q/esc: quit  ";
581	    let padded = format!("{:<width$}", bar.chars().take(w).collect::<String>(), width = w);
582	    queue!(buf, cursor::MoveTo(0, (h - 1) as u16))?;
583	    write!(buf, "\x1b[7m{padded}\x1b[0m")?;
584	
585	    stdout.write_all(&buf)?;
586	    stdout.flush()
587	}
588	
589	fn render_row(buf: &mut Vec<u8>, line: &str, selected: bool, bg: &str, row: usize, w: usize) -> io::Result<()> {
590	    use crossterm::queue;
591	    queue!(buf, cursor::MoveTo(0, row as u16), terminal::Clear(ClearType::UntilNewLine))?;
592	    if selected {
593	        let colored = with_bg(line, bg);
594	        let vis = visible_len(line);
595	        let pad = w.saturating_sub(vis);
596	        write!(buf, "\x1b[{bg}m{colored}{}\x1b[0m", " ".repeat(pad))?;
597	    } else {
598	        write!(buf, "{line}")?;
599	    }
600	    Ok(())
601	}
