603	// ── DB enrichment ─────────────────────────────────────────────────────────────
604	
605	fn enrich_hits(hits: &mut Vec<SearchHit>) {
606	    let Ok(conn) = crate::db::connect() else { return };
607	    for hit in hits.iter_mut() {
608	        if let Some(sid) = &hit.session_id {
609	            // Pull agent + remote, plus the first checkpoint's author (matching
610	            // the resolution session_list::query_db uses: name > email > os_user).
611	            if let Ok((agent, updated_at, remote, author_name, author_email, author_os_user)) =
612	                conn.query_row(
613	                    "SELECT s.agent_name, s.updated_at, COALESCE(r.remote, ''),
614	                            COALESCE(c.author_name, ''), COALESCE(c.author_email, ''),
615	                            COALESCE(c.os_user, '')
616	                     FROM sessions s
617	                     LEFT JOIN repositories r
618	                       ON (s.cwd = r.directory OR s.cwd LIKE r.directory || '/%')
619	                     LEFT JOIN checkpoints c
620	                       ON c.session_id = s.session_id
621	                      AND c.checkpoint_number = (
622	                            SELECT MIN(checkpoint_number) FROM checkpoints
623	                            WHERE session_id = s.session_id
624	                          )
625	                     WHERE s.session_id = ?1",
626	                    [sid.as_str()],
627	                    |row| Ok((
628	                        row.get::<_, String>(0)?,
629	                        row.get::<_, String>(1)?,
630	                        row.get::<_, String>(2)?,
631	                        row.get::<_, String>(3)?,
632	                        row.get::<_, String>(4)?,
633	                        row.get::<_, String>(5)?,
634	                    )),
635	                )
636	            {
637	                hit.agent      = agent;
638	                hit.updated_at = updated_at;
639	                hit.backed_up  = true;
640	                hit.remote     = remote;
641	                hit.author     = if !author_name.trim().is_empty() { author_name }
642	                                 else if !author_email.trim().is_empty() { author_email }
643	                                 else { author_os_user };
644	            }
645	        } else if let Some(dir) = &hit.repo_dir.clone() {
646	            if let Ok(remote) = conn.query_row(
647	                "SELECT COALESCE(remote, '') FROM repositories WHERE directory = ?1",
648	                [dir.as_str()],
649	                |row| row.get::<_, String>(0),
650	            ) {
651	                hit.remote = remote;
652	            }
653	        }
654	    }
655	}
