657	// ── Direct name search ────────────────────────────────────────────────────────
658	
659	fn search_sessions_by_name(query: &str) -> Vec<SearchHit> {
660	    let words: Vec<String> = query.split_whitespace().map(|w| w.to_lowercase()).collect();
661	    if words.is_empty() { return vec![]; }
662	
663	    let Ok(conn) = crate::db::connect() else { return vec![]; };
664	    let Ok(mut stmt) = conn.prepare(
665	        "SELECT session_id, session_name, cwd FROM sessions WHERE session_name != ''"
666	    ) else { return vec![]; };
667	
668	    stmt.query_map([], |row| Ok((row.get::<_,String>(0)?, row.get::<_,String>(1)?, row.get::<_,String>(2)?)))
669	        .ok()
670	        .into_iter()
671	        .flatten()
672	        .flatten()
673	        .filter_map(|(session_id, session_name, cwd): (String, String, String)| {
674	            let normalized = session_name.to_lowercase().replace(['-', '_'], " ");
675	            if words.iter().all(|w| normalized.contains(w.as_str())) {
676	                Some(SearchHit {
677	                    kind: HitKind::Session,
678	                    title: session_name,
679	                    dir: short_path(&cwd),
680	                    excerpt_lines: vec![],
681	                    session_id: Some(session_id),
682	                    repo_dir: None,
683	                    start_ts: None, hit_ts: None, branch: String::new(),
684	                    agent: String::new(), backed_up: false, updated_at: String::new(), author: String::new(),
685	                    remote: String::new(),
686	                })
687	            } else {
688	                None
689	            }
690	        })
691	        .collect()
692	}
