694	fn search_repos_by_name(query: &str) -> Vec<SearchHit> {
695	    let words: Vec<String> = query.split_whitespace().map(|w| w.to_lowercase()).collect();
696	    if words.is_empty() { return vec![]; }
697	
698	    let Ok(conn) = crate::db::connect() else { return vec![]; };
699	    let Ok(mut stmt) = conn.prepare(
700	        "SELECT name, directory, COALESCE(remote, '') FROM repositories WHERE name != ''"
701	    ) else { return vec![]; };
702	
703	    stmt.query_map([], |row| Ok((row.get::<_,String>(0)?, row.get::<_,String>(1)?, row.get::<_,String>(2)?)))
704	        .ok()
705	        .into_iter()
706	        .flatten()
707	        .flatten()
708	        .filter_map(|(name, directory, remote): (String, String, String)| {
709	            let normalized = name.to_lowercase().replace(['-', '_'], " ");
710	            if words.iter().all(|w| normalized.contains(w.as_str())) {
711	                Some(SearchHit {
712	                    kind: HitKind::Repo,
713	                    title: name,
714	                    dir: short_path(&directory),
715	                    excerpt_lines: vec![],
716	                    session_id: None,
717	                    repo_dir: Some(directory),
718	                    start_ts: None, hit_ts: None, branch: String::new(),
719	                    agent: String::new(), backed_up: false, updated_at: String::new(), author: String::new(),
720	                    remote,
721	                })
722	            } else {
723	                None
724	            }
725	        })
726	        .collect()
727	}
728	
729	// ── Helpers ───────────────────────────────────────────────────────────────────
730	
731	fn rel_time_hit(iso: &str) -> String {
732	    if iso.is_empty() { return String::new(); }
733	    let Ok(dt) = DateTime::parse_from_rfc3339(iso) else { return String::new(); };
734	    let secs = (Utc::now() - dt.with_timezone(&Utc)).num_seconds().max(0);
735	    if secs < 604_800 {
736	        match secs {
737	            s if s < 60     => "just now".into(),
738	            s if s < 3_600  => format!("{} min ago", s / 60),
739	            s if s < 86_400 => format!("{} hr ago",  s / 3_600),
740	            s               => format!("{} day{} ago", s / 86_400, if s / 86_400 == 1 { "" } else { "s" }),
741	        }
742	    } else {
743	        dt.with_timezone(&chrono::Local).format("%m/%d/%y").to_string()
744	    }
745	}
746	
747	fn age_secs_hit(iso: &str) -> i64 {
748	    if iso.is_empty() { return i64::MAX; }
749	    let Ok(dt) = DateTime::parse_from_rfc3339(iso) else { return i64::MAX; };
750	    (Utc::now() - dt.with_timezone(&Utc)).num_seconds().max(0)
751	}
752	
753	use super::agent_color;
754	
755	fn with_bg(s: &str, bg: &str) -> String {
756	    let t = crate::theme::get();
757	    let dim_esc   = format!("\x1b[{}m", t.text_dim);
758	    let faint_esc = format!("\x1b[{}m", t.text_faint);
759	    let sel_dim   = format!("\x1b[{}m", t.sel_text_dim);
760	    let reinsert  = format!("\x1b[0m\x1b[{bg}m");
761	    let body = s.replace("\x1b[0m", &reinsert)
762	                .replace(&dim_esc,   &sel_dim)
763	                .replace(&faint_esc, &sel_dim);
764	    format!("\x1b[{bg}m{body}")
765	}
766	
767	fn visible_len(s: &str) -> usize {
768	    let mut w = 0usize;
769	    let mut chars = s.chars().peekable();
770	    while let Some(c) = chars.next() {
771	        if c == '\x1b' {
772	            for nc in chars.by_ref() { if nc.is_ascii_alphabetic() { break; } }
773	        } else {
774	            w += 1;
775	        }
776	    }
777	    w
778	}
779	
780	fn short_path(path: &str) -> String {
781	    let home = std::env::var("HOME").unwrap_or_default();
782	    if !home.is_empty() && path.starts_with(&home) {
783	        format!("~{}", &path[home.len()..])
784	    } else {
785	        path.to_string()
786	    }
787	}
