212	fn attribute(authors: &[CheckpointAuthor], ts: &str) -> Option<String> {
213	    let dt = DateTime::parse_from_rfc3339(ts).ok()?.with_timezone(&Utc);
214	    // Earliest checkpoint whose last_turn_ts >= the card's timestamp.
215	    for a in authors {
216	        if a.last_turn_ts >= dt {
217	            return Some(a.label.clone());
218	        }
219	    }
220	    // Card's timestamp is past every checkpoint we've seen — attribute to
221	    // the most recent author (latest checkpoint).
222	    authors.last().map(|a| a.label.clone())
223	}
