244	fn find_session(id: &str) -> Option<PathBuf> {
245	    let p = PathBuf::from(id);
246	    if p.exists() { return Some(p); }
247	    if let Ok(home) = std::env::var("HOME") {
248	        let projects = PathBuf::from(&home).join(".claude/projects");
249	        if let Ok(entries) = std::fs::read_dir(&projects) {
250	            for entry in entries.flatten() {
251	                let candidate = entry.path().join(format!("{id}.jsonl"));
252	                if candidate.exists() { return Some(candidate); }
253	            }
254	        }
255	    }
256	    // Fall back to extracting the latest checkpoint's full.jsonl from the
257	    // entire/checkpoints/v1 branch. Used when this session was authored on
258	    // another machine and never produced a local Claude Code log.
259	    extract_from_checkpoint(id)
