262	fn extract_from_checkpoint(session_id: &str) -> Option<PathBuf> {
263	    let conn = crate::db::connect().ok()?;
264	    let jsonl_path: String = conn.query_row(
265	        "SELECT jsonl_path FROM checkpoints
266	         WHERE session_id = ?1
267	           AND jsonl_path IS NOT NULL
268	         ORDER BY checkpoint_number DESC
269	         LIMIT 1",
270	        [session_id],
271	        |row| row.get(0),
272	    ).ok()?;
273	
274	    // The stored `repo_dir` is whichever repo's index pass last wrote this
275	    // checkpoint row — sometimes stale (the file may since have been removed
276	    // from that repo's branch, or the same file lives in multiple repos'
277	    // shared checkpoint branch). Try the recorded repo_dir first, then fall
278	    // back to every other tracked repo. Whichever clone actually has the path
279	    // in its checkpoint branch wins.
280	    let preferred: Option<String> = conn.query_row(
281	        "SELECT repo_dir FROM checkpoints
282	         WHERE session_id = ?1 AND repo_dir IS NOT NULL
283	         ORDER BY checkpoint_number DESC LIMIT 1",
284	        [session_id], |row| row.get(0),
285	    ).ok();
286	
287	    let mut candidates: Vec<String> = Vec::new();
288	    if let Some(p) = preferred { candidates.push(p); }
289	    if let Ok(mut stmt) = conn.prepare("SELECT directory FROM repositories") {
290	        if let Ok(rows) = stmt.query_map([], |row| row.get::<_, String>(0)) {
291	            for r in rows.flatten() {
292	                if !candidates.contains(&r) { candidates.push(r); }
293	            }
294	        }
295	    }
296	
297	    let bytes = candidates.iter()
298	        .find_map(|dir| crate::commands::index::git_show(dir, &jsonl_path).ok())?;
299	
300	    let home = std::env::var("HOME").ok()?;
301	    let cache_dir = PathBuf::from(&home).join(".gossamer").join("sessions");
302	    std::fs::create_dir_all(&cache_dir).ok()?;
303	    let cache_path = cache_dir.join(format!("{session_id}.jsonl"));
304	    std::fs::write(&cache_path, &bytes).ok()?;
305	    Some(cache_path)
306	}
