308	// ── Parsing ───────────────────────────────────────────────────────────────────
309	
310	fn parse(raw: &str, agent: &str) -> Vec<Card> {
311	    let mut tool_names: HashMap<String, String> = HashMap::new();
312	    for line in raw.lines() {
313	        if let Ok(v) = serde_json::from_str::<Value>(line) {
314	            if let Some(blocks) = v["message"]["content"].as_array() {
315	                for b in blocks {
316	                    if b["type"].as_str() == Some("tool_use") {
317	                        if let (Some(id), Some(name)) = (b["id"].as_str(), b["name"].as_str()) {
318	                            tool_names.insert(id.to_string(), name.to_string());
319	                        }
320	                    }
321	                }
322	            }
323	        }
324	    }
325	
326	    let mut cards: Vec<Card> = Vec::new();
327	    let mut first_cwd    = String::new();
328	    let mut first_branch = String::new();
329	    let mut first_ts     = String::new();
330	    let mut title: Option<String> = None;
331	
332	    for line in raw.lines() {
333	        if line.trim().is_empty() { continue; }
334	        let Ok(v) = serde_json::from_str::<Value>(line) else { continue };
335	        let ts = v["timestamp"].as_str().unwrap_or("").to_string();
336	        if first_ts.is_empty() && !ts.is_empty() { first_ts = ts.clone(); }
337	
338	        match v["type"].as_str() {
339	            Some("custom-title") => {
340	                title = v["customTitle"].as_str().map(str::to_string);
341	            }
342	            Some("system") => {
343	                if let Some(c) = v["cwd"].as_str() { if first_cwd.is_empty() { first_cwd = c.to_string(); } }
344	                let content = v["content"].as_str().unwrap_or("").to_string();
345	                if !content.is_empty() {
346	                    let subtype = v["subtype"].as_str().unwrap_or("system").replace('_', " ");
347	                    cards.push(Card::System { ts, subtype, content });
348	                }
349	            }
350	            Some("user") => {
351	                if let Some(c) = v["cwd"].as_str()       { if first_cwd.is_empty()    { first_cwd    = c.to_string(); } }
352	                if let Some(b) = v["gitBranch"].as_str() { if first_branch.is_empty() { first_branch = b.to_string(); } }
353	                let parts = parse_user(&v["message"]["content"], &tool_names);
354	                if !parts.is_empty() { cards.push(Card::UserMsg { ts, parts, author: None }); }
355	            }
356	            Some("assistant") => {
357	                let parts = parse_asst(&v["message"]["content"]);
358	                if !parts.is_empty() { cards.push(Card::AsstMsg { ts, parts }); }
359	            }
360	            _ => {}
361	        }
362	    }
363	
364	    let mut result = vec![Card::Header { title, cwd: first_cwd, branch: first_branch, ts: first_ts, agent: agent.to_string() }];
365	    result.extend(cards);
366	
367	    // Merge each pure tool-result UserMsg into the preceding AsstMsg.
368	    let mut i = 1;
369	    while i < result.len() {
370	        let is_pure_results = if let Card::UserMsg { parts, .. } = &result[i] {
371	            parts.iter().all(|p| matches!(p, UserPart::ToolResult { .. }))
372	        } else { false };
373	
374	        if is_pure_results && matches!(&result[i - 1], Card::AsstMsg { .. }) {
375	            let tool_results: Vec<(String, String, bool)> =
376	                if let Card::UserMsg { parts, .. } = &result[i] {
377	                    parts.iter().filter_map(|p| {
378	                        if let UserPart::ToolResult { id, content, is_error, .. } = p {
379	                            Some((id.clone(), content.clone(), *is_error))
380	                        } else { None }
381	                    }).collect()
382	                } else { vec![] };
383	
384	            if let Card::AsstMsg { parts: asst_parts, .. } = &mut result[i - 1] {
385	                for part in asst_parts.iter_mut() {
386	                    if let AsstPart::ToolCall { id, result: res, .. } = part {
387	                        if let Some((_, content, is_error)) =
388	                            tool_results.iter().find(|(rid, _, _)| rid == id)
389	                        {
390	                            *res = Some((content.clone(), *is_error));
391	                        }
392	                    }
393	                }
394	            }
395	            result.remove(i);
396	        } else {
397	            i += 1;
398	        }
399	    }
400	
401	    // Merge consecutive AsstMsg cards so the assistant name appears only once per run.
402	    let mut i = 1;
403	    while i < result.len() {
404	        if matches!(&result[i - 1], Card::AsstMsg { .. }) && matches!(&result[i], Card::AsstMsg { .. }) {
405	            if let Card::AsstMsg { parts: new_parts, .. } = result.remove(i) {
406	                if let Card::AsstMsg { parts, .. } = &mut result[i - 1] {
407	                    parts.extend(new_parts);
408	                }
409	            }
410	        } else {
411	            i += 1;
412	        }
413	    }
414	
415	    // Split each AsstMsg into a text-only AsstMsg (if any text) + a ToolRound (if any tools).
416	    let mut split: Vec<Card> = Vec::with_capacity(result.len());
417	    for card in result {
418	        match card {
419	            Card::AsstMsg { ts, parts } => {
420	                let (text_parts, tool_parts): (Vec<AsstPart>, Vec<AsstPart>) =
421	                    parts.into_iter().partition(|p| matches!(p, AsstPart::Text(_)));
422	                if !text_parts.is_empty() { split.push(Card::AsstMsg  { ts, parts: text_parts }); }
423	                if !tool_parts.is_empty() { split.push(Card::ToolRound { parts: tool_parts }); }
424	            }
425	            other => split.push(other),
426	        }
427	    }
428	    let mut result = split;
429	
430	    // Merge adjacent ToolRound cards (can arise when consecutive asst turns were all-tools).
431	    let mut i = 1;
432	    while i < result.len() {
433	        if matches!(&result[i - 1], Card::ToolRound { .. }) && matches!(&result[i], Card::ToolRound { .. }) {
434	            if let Card::ToolRound { parts: new_parts } = result.remove(i) {
435	                if let Card::ToolRound { parts } = &mut result[i - 1] {
436	                    parts.extend(new_parts);
437	                }
438	            }
439	        } else {
440	            i += 1;
441	        }
442	    }
443	
444	    result
445	}
446	
447	fn parse_user(content: &Value, tool_names: &HashMap<String, String>) -> Vec<UserPart> {
448	    let mut out = Vec::new();
449	    match content {
450	        Value::String(s) if !s.trim().is_empty() => out.push(UserPart::Text(s.clone())),
451	        Value::Array(blocks) => {
452	            for b in blocks {
453	                match b["type"].as_str() {
454	                    Some("text") => {
455	                        if let Some(t) = b["text"].as_str() {
456	                            if !t.trim().is_empty() { out.push(UserPart::Text(t.to_string())); }
457	                        }
458	                    }
459	                    Some("tool_result") => {
460	                        let id = b["tool_use_id"].as_str().unwrap_or("").to_string();
461	                        let name = tool_names.get(&id).cloned().unwrap_or_else(|| "tool".to_string());
462	                        let is_error = b["is_error"].as_bool().unwrap_or(false);
463	                        let content = match &b["content"] {
464	                            Value::String(s) => s.clone(),
465	                            Value::Array(arr) => arr.iter()
466	                                .filter(|x| x["type"].as_str() == Some("text"))
467	                                .filter_map(|x| x["text"].as_str())
468	                                .collect::<Vec<_>>().join("\n"),
469	                            _ => String::new(),
470	                        };
471	                        out.push(UserPart::ToolResult { id, name, content, is_error });
472	                    }
473	                    _ => {}
474	                }
475	            }
476	        }
477	        _ => {}
478	    }
479	    out
480	}
481	
482	fn parse_asst(content: &Value) -> Vec<AsstPart> {
483	    let mut out = Vec::new();
484	    match content {
485	        Value::String(s) if !s.trim().is_empty() => out.push(AsstPart::Text(s.clone())),
486	        Value::Array(blocks) => {
487	            for b in blocks {
488	                match b["type"].as_str() {
489	                    Some("text") => {
490	                        if let Some(t) = b["text"].as_str() {
491	                            if !t.trim().is_empty() { out.push(AsstPart::Text(t.to_string())); }
492	                        }
493	                    }
494	                    Some("tool_use") => {
495	                        out.push(AsstPart::ToolCall {
496	                            id:     b["id"].as_str().unwrap_or("").to_string(),
497	                            name:   b["name"].as_str().unwrap_or("unknown").to_string(),
498	                            input:  b["input"].clone(),
499	                            result: None,
500	                        });
501	                    }
502	                    _ => {}
503	                }
504	            }
505	        }
506	        _ => {}
507	    }
508	    out
509	}
510	
511	// ── Text extraction (for clipboard) ──────────────────────────────────────────
512	
513	fn card_text(card: &Card) -> String {
514	    let mut out = String::new();
515	    match card {
516	        Card::RepoLink { name, dir, branch } => {
517	            out.push_str(name); out.push('\n');
518	            out.push_str(dir);  out.push('\n');
519	            if !branch.is_empty() { out.push_str(branch); out.push('\n'); }
