748	fn render_one_tool_call(part: &AsstPart, w: usize) -> Vec<String> {
749	    let t = crate::theme::get();
750	    let mut lines = Vec::new();
751	    if let AsstPart::ToolCall { name, input, result, .. } = part {
752	        lines.push(format!("\x1b[{lb}m  ▶ {name}\x1b[0m", lb = t.label));
753	        if let Some(obj) = input.as_object() {
