755	            for (_, v) in obj.iter().take(4) {
756	                let raw_val = if let Value::String(s) = v { s.clone() } else { v.to_string() };
757	                let first_line = raw_val.lines().next().unwrap_or("");
758	                let preview: String = first_line.chars().take(120).collect();
759	                let suffix = if raw_val.lines().count() > 1 || first_line.chars().count() > 120 { " …" } else { "" };
760	                let col = if is_first { t.text_primary } else { t.text_secondary };
761	                lines.push(format!("\x1b[{col}m    {preview}{suffix}\x1b[0m"));
762	                is_first = false;
763	            }
764	            if obj.len() > 4 {
765	                lines.push(format!("\x1b[{ft}m    … {} more fields\x1b[0m", obj.len() - 4, ft = t.text_faint));
766	            }
767	        }
768	        if let Some((content, is_error)) = result {
769	            lines.push(format!("\x1b[{ft}m  ────────────────────────────────────────\x1b[0m", ft = t.text_faint));
770	            let col = if *is_error { t.error } else { t.text_dim };
771	            let visible: Vec<&str> = content.lines()
772	                .filter(|l| !l.trim().is_empty()).take(8).collect();
773	            for l in wrap(&visible.join("\n"), w.saturating_sub(4)) {
774	                lines.push(format!("\x1b[{col}m    {l}\x1b[0m"));
775	            }
776	            let total = content.lines().filter(|l| !l.trim().is_empty()).count();
777	            if total > 8 {
778	                lines.push(format!("\x1b[{ft}m    … {} more lines\x1b[0m", total - 8, ft = t.text_faint));
779	            }
780	        }
781	        lines.push(String::new());
782	    }
783	    lines
784	}
