830	fn git_current_branch(cwd: &str) -> Option<String> {
831	    let out = std::process::Command::new("git")
832	        .args(["rev-parse", "--abbrev-ref", "HEAD"])
833	        .current_dir(cwd)
834	        .output()
835	        .ok()?;
836	    if !out.status.success() { return None; }
837	    let s = String::from_utf8_lossy(&out.stdout).trim().to_string();
838	    if s.is_empty() || s == "HEAD" { None } else { Some(s) }
839	}
840	
841	fn create_resume_worktree(cwd: &str, branch: &str) -> Option<String> {
842	    let root_out = std::process::Command::new("git")
843	        .args(["rev-parse", "--show-toplevel"])
844	        .current_dir(cwd)
845	        .output()
846	        .ok()?;
847	    if !root_out.status.success() { return None; }
848	    let repo_root = String::from_utf8_lossy(&root_out.stdout).trim().to_string();
849	
850	    let repo_path = std::path::Path::new(&repo_root);
851	    let parent = repo_path.parent()?;
852	    let repo_name = repo_path.file_name()?.to_str()?;
853	    let wt_path = parent.join(format!("{repo_name}-{branch}"));
854	
855	    // Branch already exists; add a worktree pointing at it.
856	    let _ = std::process::Command::new("git")
857	        .args(["worktree", "add", wt_path.to_str()?, branch])
858	        .current_dir(&repo_root)
859	        .output();
860	
861	    if wt_path.exists() { Some(wt_path.to_string_lossy().to_string()) } else { None }
862	}
863	
864	fn resume_via_entire(dir: &str, branch: &str) {
865	    use std::os::unix::process::CommandExt;
866	
867	    let launch_dir = if !branch.is_empty() {
868	        let current = git_current_branch(dir);
869	        if current.as_deref() != Some(branch) {
870	            create_resume_worktree(dir, branch).unwrap_or_else(|| dir.to_string())
871	        } else {
872	            dir.to_string()
873	        }
874	    } else {
875	        dir.to_string()
876	    };
877	
878	    let mut entire = std::process::Command::new("entire");
879	    entire.arg("resume").current_dir(&launch_dir);
880	    if !branch.is_empty() { entire.arg(branch); }
881	
882	    let Ok(out) = entire.output() else { eprintln!("entire resume failed"); return; };
883	
884	    let cmd_str = String::from_utf8_lossy(&out.stdout).trim().to_string();
885	    if cmd_str.is_empty() { eprintln!("entire resume returned no command"); return; }
886	
887	    let mut parts = cmd_str.split_whitespace();
888	    let Some(prog) = parts.next() else { return; };
889	    let args: Vec<&str> = parts.collect();
890	    let err = std::process::Command::new(prog).args(&args).current_dir(&launch_dir).exec();
891	    eprintln!("exec failed: {err}");
892	}
