894	/// Find a Claude session by ID. Returns `(cwd, git_branch)` from the JSONL if found,
895	/// so `claude --resume` can be run from the correct directory and branch is known.
896	fn find_claude_session_cwd(session_id: &str) -> Option<(String, String)> {
897	    use std::io::BufRead;
898	    let home = std::env::var("HOME").ok()?;
899	    let projects = std::path::PathBuf::from(&home).join(".claude/projects");
900	    for dir in std::fs::read_dir(&projects).ok()?.flatten() {
901	        let jsonl = dir.path().join(format!("{session_id}.jsonl"));
902	        if !jsonl.exists() { continue; }
903	        let Ok(file) = std::fs::File::open(&jsonl) else { return Some((String::new(), String::new())); };
904	        let mut cwd = String::new();
905	        let mut branch = String::new();
906	        for line in std::io::BufReader::new(file).lines().flatten() {
907	            let Ok(v) = serde_json::from_str::<serde_json::Value>(&line) else { continue };
908	            if matches!(v["type"].as_str(), Some("user") | Some("system")) {
909	                if cwd.is_empty() {
910	                    if let Some(c) = v["cwd"].as_str() { cwd = c.to_string(); }
911	                }
912	                if branch.is_empty() {
913	                    if let Some(b) = v["gitBranch"].as_str() { branch = b.to_string(); }
914	                }
915	                if !cwd.is_empty() && !branch.is_empty() { break; }
916	            }
917	        }
918	        return Some((cwd, branch));
919	    }
920	    None
921	}
922	
923	fn do_resume(_agent: &str, session_id: &str, session_branch: &str, session_cwd: &str) {
924	    let current = git_current_branch(session_cwd);
925	    let same_branch = !session_branch.is_empty()
926	        && current.as_deref() == Some(session_branch);
927	
928	    let dir = if same_branch || session_branch.is_empty() {
929	        session_cwd.to_string()
930	    } else {
931	        create_resume_worktree(session_cwd, session_branch)
932	            .unwrap_or_else(|| session_cwd.to_string())
933	    };
934	
935	    resume_session(session_id, &dir);
936	}
937	
938	/// Resume a session by ID, falling back to `entire resume` if the Claude JSONL is absent.
939	/// `fallback_cwd` is used for `entire resume` if the Claude session isn't found.
940	pub fn resume_session(session_id: &str, fallback_cwd: &str) {
941	    use std::os::unix::process::CommandExt;
942	    if let Some((session_cwd, session_branch)) = find_claude_session_cwd(session_id) {
943	        let launch_dir = if session_cwd.is_empty() || !std::path::Path::new(&session_cwd).exists() {
944	            fallback_cwd.to_string()
945	        } else {
946	            session_cwd
947	        };
948	        let err = std::process::Command::new("claude")
949	            .arg("--resume")
950	            .arg(session_id)
951	            .current_dir(&launch_dir)
952	            .exec();
953	        eprintln!("exec failed: {err}");
954	        // exec failed — fall back to entire resume, checking out the session branch first
955	        resume_via_entire(&launch_dir, &session_branch);
956	    } else {
957	        resume_via_entire(fallback_cwd, "");
958	    }
959	}
