963	fn build_flat(
964	    cards: &[Card],
965	    term_w: usize,
966	    collapsed: &std::collections::HashSet<usize>,
967	) -> (Vec<(usize, String)>, Vec<Selectable>, Vec<usize>) {
968	    let w = term_w.saturating_sub(2);
969	    let mut flat: Vec<(usize, String)> = Vec::new();
970	    let mut selectables: Vec<Selectable> = Vec::new();
971	    let mut starts: Vec<usize> = Vec::new();
972	
973	    // Pull the agent name from the Header card so render_card can use it.
974	    let agent: &str = cards.iter().find_map(|c| {
975	        if let Card::Header { agent, .. } = c { Some(agent.as_str()) } else { None }
976	    }).unwrap_or("");
977	
978	    for (card_idx, card) in cards.iter().enumerate() {
979	        if let Card::ToolRound { parts } = card {
980	            if collapsed.contains(&card_idx) {
981	                let si = selectables.len();
982	                starts.push(flat.len());
983	                selectables.push(Selectable::Card(card_idx));
984	                for l in render_tool_summary(parts) { flat.push((si, l)); }
985	            } else {
986	                // Header row (collapses the round when space is pressed)
987	                let si = selectables.len();
988	                starts.push(flat.len());
989	                selectables.push(Selectable::ToolHeader(card_idx));
990	                for l in render_tool_header(parts) { flat.push((si, l)); }
991	                // One selectable per individual tool call
992	                for (tool_idx, part) in parts.iter().enumerate() {
993	                    let si = selectables.len();
994	                    starts.push(flat.len());
995	                    selectables.push(Selectable::ToolCall(card_idx, tool_idx));
996	                    for l in render_one_tool_call(part, w) { flat.push((si, l)); }
997	                }
998	            }
999	        } else {
1000	            let si = selectables.len();
1001	            starts.push(flat.len());
1002	            selectables.push(Selectable::Card(card_idx));
1003	            for l in render_card(card, w, agent) { flat.push((si, l)); }
1004	        }
1005	    }
1006	
1007	    (flat, selectables, starts)
1008	}
1009	
1010	// `Back` returns to whatever called show (the sessions list, the repo TUI, or
1011	// the CLI). `Quit` propagates a full-app exit so q from anywhere quits.
1012	enum PagerOutcome { Back, Quit, Resume, Delete, GoToSessions, GoToRepo(String) }
1013	
1014	fn pager(cards: &[Card], start_ts: Option<&str>) -> Result<PagerOutcome> {
1015	    let (term_w, term_h) = terminal::size().unwrap_or((120, 40));
1016	    let mut w = term_w as usize;
1017	    let mut h = (term_h as usize).saturating_sub(1);
1018	
1019	    let mut collapsed: std::collections::HashSet<usize> = cards.iter().enumerate()
1020	        .filter_map(|(i, c)| if matches!(c, Card::ToolRound { .. }) { Some(i) } else { None })
1021	        .collect();
1022	
1023	    let (mut flat, mut selectables, mut starts) = build_flat(&cards, w, &collapsed);
1024	
1025	    let mut stdout = io::stdout();
1026	
1027	    let orig_hook = std::panic::take_hook();
1028	    std::panic::set_hook(Box::new(move |info| {
1029	        let mut out = io::stdout();
1030	        let _ = execute!(out, LeaveAlternateScreen, cursor::Show);
1031	        let _ = terminal::disable_raw_mode();
1032	        orig_hook(info);
1033	    }));
1034	
1035	    terminal::enable_raw_mode()?;
1036	    execute!(stdout, EnterAlternateScreen, cursor::Hide)?;
1037	
1038	    // If a target timestamp was given, jump to the first card whose ts matches.
1039	    // Otherwise land on the first non-navigation card (skip RepoLink and Header).
1040	    let initial_sel = start_ts.and_then(|ts| {
1041	        cards.iter().enumerate().find_map(|(ci, card)| {
1042	            let card_ts = match card {
1043	                Card::UserMsg { ts, .. } | Card::AsstMsg { ts, .. } | Card::System { ts, .. } => ts.as_str(),
1044	                _ => return None,
1045	            };
1046	            if card_ts == ts {
1047	                selectables.iter().position(|s| *s == Selectable::Card(ci))
1048	            } else {
1049	                None
1050	            }
1051	        })
1052	    }).unwrap_or_else(|| selectables.len().saturating_sub(1));
1053	
1054	    let mut sel: usize = initial_sel;
1055	    let mut scroll: usize = 0;
1056	    let mut flash:  Option<&str> = None;
1057	    let mut awaiting_delete = false;
1058	
1059	    let result: Result<PagerOutcome> = loop {
1060	        let s = starts[sel];
1061	        let e = starts.get(sel + 1).copied().unwrap_or(flat.len());
1062	        if s < scroll          { scroll = s; }
1063	        else if e > scroll + h { scroll = e.saturating_sub(h); }
1064	
1065	        if let Err(err) = draw(&mut stdout, &flat, &starts, sel, scroll, h, w, selectables.len(), flash) {
1066	            break Err(anyhow::anyhow!(err));
1067	        }
1068	
1069	        match event::read() {
1070	            Err(e) => break Err(e.into()),
1071	            Ok(Event::Key(k)) => {
1072	                let prev_flash = flash.take();
1073	                match (k.code, k.modifiers) {
1074	                    (KeyCode::Char('q'), _) => break Ok(PagerOutcome::Quit),
1075	                    (KeyCode::Char('c'), KeyModifiers::CONTROL) => break Ok(PagerOutcome::Quit),
1076	                    (KeyCode::Esc | KeyCode::Left, _) => break Ok(PagerOutcome::Back),
1077	                    (KeyCode::Char('r'), _) => break Ok(PagerOutcome::Resume),
1078	                    (KeyCode::Char('d'), _) => {
1079	                        awaiting_delete = true;
1080	                        flash = Some("  Delete session? Press y to confirm, any other key to cancel  ");
1081	                        continue;
1082	                    }
1083	                    (KeyCode::Char('y'), _) if awaiting_delete => {
1084	                        break Ok(PagerOutcome::Delete);
1085	                    }
1086	
1087	                    (KeyCode::Down | KeyCode::Char('j'), _) => {
1088	                        if sel + 1 < selectables.len() { sel += 1; }
1089	                    }
1090	                    (KeyCode::Up | KeyCode::Char('k'), _) => {
1091	                        if sel > 0 { sel -= 1; }
1092	                    }
1093	                    (KeyCode::Char('g'), _) => { sel = 0; }
1094	                    (KeyCode::Char('G'), _) => { sel = selectables.len().saturating_sub(1); }
1095	                    (KeyCode::Char('u'), _) | (KeyCode::PageUp, _) => {
1096	                        scroll = scroll.saturating_sub(h / 2);
1097	                        sel = flat[scroll].0;
1098	                    }
1099	                    (KeyCode::PageDown, _) => {
1100	                        scroll = (scroll + h / 2).min(flat.len().saturating_sub(h));
1101	                        sel = flat[scroll].0;
1102	                    }
1103	
1104	                    (KeyCode::Char('y'), _) | (KeyCode::Char('c'), _) => {
1105	                        let text = match &selectables[sel] {
1106	                            Selectable::Card(ci)         => card_text(&cards[*ci]),
1107	                            Selectable::ToolHeader(ci)   => card_text(&cards[*ci]),
1108	                            Selectable::ToolCall(ci, ti) => {
1109	                                if let Card::ToolRound { parts } = &cards[*ci] {
1110	                                    parts.get(*ti).map_or(String::new(), tool_call_text)
1111	                                } else { String::new() }
1112	                            }
1113	                        };
1114	                        copy_to_clipboard(&text);
1115	                        flash = Some("  ✓ copied to clipboard  ");
1116	                    }
1117	
1118	                    // Space/Right/Enter: expand ToolRound, collapse via header, or navigate
1119	                    (KeyCode::Char(' ') | KeyCode::Right | KeyCode::Enter, _) => {
1120	                        let expand_action = match &selectables[sel] {
1121	                            Selectable::Card(ci) if matches!(&cards[*ci], Card::ToolRound { .. }) => {
1122	                                Some((true, *ci))
1123	                            }
1124	                            Selectable::ToolHeader(ci) => Some((false, *ci)),
1125	                            _ => None,
1126	                        };
1127	                        if let Some((expand, card_idx)) = expand_action {
1128	                            if expand { collapsed.remove(&card_idx); } else { collapsed.insert(card_idx); }
1129	                            let (nf, ns, nst) = build_flat(cards, w, &collapsed);
1130	                            flat   = nf;
1131	                            starts = nst;
1132	                            sel = if expand {
1133	                                ns.iter().position(|s| *s == Selectable::ToolHeader(card_idx))
1134	                            } else {
1135	                                ns.iter().position(|s| *s == Selectable::Card(card_idx))
1136	                            }.unwrap_or_else(|| sel.min(ns.len().saturating_sub(1)));
1137	                            selectables = ns;
1138	                        } else if let Selectable::Card(ci) = &selectables[sel] {
1139	                            match &cards[*ci] {
1140	                                Card::RepoLink { dir, .. } => {
1141	                                    break Ok(PagerOutcome::GoToRepo(dir.clone()));
1142	                                }
1143	                                Card::Header { .. } => {
1144	                                    break Ok(PagerOutcome::GoToSessions);
1145	                                }
1146	                                _ => { flash = prev_flash; }
1147	                            }
1148	                        } else {
1149	                            flash = prev_flash;
1150	                        }
1151	                    }
1152	
1153	                    _ => { awaiting_delete = false; flash = prev_flash; }
1154	                }
1155	            }
1156	            Ok(Event::Resize(new_w, new_h)) => {
1157	                w = new_w as usize;
1158	                h = (new_h as usize).saturating_sub(1);
1159	                let (nf, ns, nst) = build_flat(&cards, w, &collapsed);
1160	                flat = nf; selectables = ns; starts = nst;
1161	                execute!(stdout, terminal::Clear(ClearType::All)).ok();
1162	            }
1163	            Ok(_) => {}
1164	        }
1165	    };
1166	
1167	    execute!(stdout, LeaveAlternateScreen, cursor::Show)?;
1168	    terminal::disable_raw_mode()?;
1169	    result
1170	}
1171	
1172	fn draw(
1173	    stdout: &mut impl Write,
1174	    flat:   &[(usize, String)],
1175	    starts: &[usize],
1176	    sel:    usize,
1177	    scroll: usize,
1178	    h:      usize,
1179	    w:      usize,
1180	    total:  usize,
1181	    flash:  Option<&str>,
1182	) -> io::Result<()> {
1183	    use crossterm::queue;
1184	    let accent = crate::theme::get().accent;
1185	
1186	    let end = (scroll + h).min(flat.len());
1187	
1188	    // Build the entire frame into one buffer; flush once to eliminate flicker.
1189	    // Use explicit cursor::MoveTo per row so embedded newlines in content can't
1190	    // shift subsequent rows into the wrong position.
1191	    let mut buf: Vec<u8> = Vec::with_capacity((w + 40) * (h + 2));
1192	
1193	    for row in 0..h {
1194	        queue!(buf, cursor::MoveTo(0, row as u16), terminal::Clear(ClearType::UntilNewLine))?;
1195	
1196	        let flat_idx = scroll + row;
1197	        if flat_idx < end {
1198	            let (card_idx, line) = &flat[flat_idx];
1199	            if *card_idx == sel {
1200	                let is_first = flat_idx == 0 || flat[flat_idx - 1].0 != sel;
1201	                if is_first {
1202	                    let t = crate::theme::get();
1203	                    let bg = t.sel_bg;
1204	                    let colored = super::with_bg(line, bg);
1205	                    let pad = w.saturating_sub(2 + super::visible_width(line));
1206	                    write!(buf, "\x1b[{bg}m  {colored}{}\x1b[0m", " ".repeat(pad))?;
1207	                } else {
1208	                    write!(buf, "\x1b[{}m▌\x1b[0m {line}", accent)?;
1209	                }
1210	            } else {
1211	                write!(buf, "  ")?;
1212	                buf.extend_from_slice(line.as_bytes());
1213	            }
1214	        }
1215	    }
1216	
1217	    // Status bar
1218	    let sel_end = starts.get(sel + 1).copied().unwrap_or(flat.len());
1219	    let base = format!(
1220	        "  {}/{} msgs  lines {}-{}  j/k ↑↓ navigate  u/PgDn page  g/G ends  y/c copy  r resume  d delete  q quit  ",
1221	        sel + 1, total, starts[sel] + 1, sel_end,
1222	    );
1223	    let bar = if let Some(msg) = flash {
1224	        let skip = msg.chars().count();
1225	        let rest: String = base.chars().skip(skip).collect();
1226	        format!("{msg}{rest}")
1227	    } else {
1228	        base
1229	    };
1230	    let bar_display: String = bar.chars().take(w).collect();
1231	    let padded = format!("{bar_display:width$}", width = w);
1232	    queue!(buf, cursor::MoveTo(0, h as u16))?;
1233	    write!(buf, "\x1b[7m{padded}\x1b[0m")?;
1234	
1235	    stdout.write_all(&buf)?;
1236	    stdout.flush()
1237	}
