234	                    KeyCode::Char('q') => Cmd::Break,
235	                    KeyCode::Char('c') if k.modifiers.contains(crossterm::event::KeyModifiers::CONTROL) => {
236	                        execute!(stdout, LeaveAlternateScreen, cursor::Show).ok();
237	                        terminal::disable_raw_mode().ok();
238	                        std::process::exit(0);
239	                    }
240	                    KeyCode::Esc | KeyCode::Char('h') | KeyCode::Left => Cmd::Back,
241	                    KeyCode::Up   | KeyCode::Char('k') => { if *sel > 0 { *sel -= 1; } Cmd::None }
242	                    KeyCode::Down | KeyCode::Char('j') => { if *sel + 1 < sessions.len() { *sel += 1; } Cmd::None }
243	                    KeyCode::Char('g') => { *sel = 0; Cmd::None }
244	                    KeyCode::Char('G') => { *sel = sessions.len().saturating_sub(1); Cmd::None }
245	                    KeyCode::Char(' ') | KeyCode::Right => {
246	                        if sessions.is_empty() { Cmd::None }
247	                        else { Cmd::ShowSession(sessions[*sel].session_id.clone()) }
248	                    }
249	                    KeyCode::Char('r') => {
250	                        if sessions.is_empty() { Cmd::None }
251	                        else { Cmd::ResumeSession(sessions[*sel].session_id.clone(), repos[*repo_idx].directory.clone()) }
252	                    }
253	                    KeyCode::Char('/') => match collect_search_query(stdout, w, h) {
254	                        Some(q) if !q.trim().is_empty() => Cmd::Search(q),
255	                        _ => Cmd::Redraw,
256	                    },
257	                    KeyCode::Char('n') => match collect_text_input(stdout, "  new worktree branch: ", w, h) {
258	                        Some(b) if !b.trim().is_empty() => Cmd::NewWorktree(b.trim().to_string()),
259	                        _ => Cmd::Redraw,
260	                    },
261	                    KeyCode::Char('s') => {
262	                        let repo_dir = repos[*repo_idx].directory.clone();
263	                        match new_session_wizard(stdout, &repo_dir, w, h) {
264	                            Some(cfg) => Cmd::NewSession(cfg),
265	                            None => Cmd::Redraw,
266	                        }
267	                    }
268	                    KeyCode::Char('t') => Cmd::Tidy,
269	                    _ => Cmd::None,
270	                },
271	            },
272	            Event::Resize(_, _) => Cmd::Redraw,
273	            _ => Cmd::None,
274	        };
275	
276	        match cmd {
277	            Cmd::None => {}
278	            Cmd::Break => return Ok(Some(TuiOutcome::Quit)),
279	            Cmd::Back => {
280	                stack.pop();
281	                if stack.is_empty() { break; }
282	            }
283	            Cmd::PushSessions(idx) => {
284	                let sessions = session_list::fetch(Scope::Repo(&repos[idx]), true);
285	                let worktrees = fetch_worktrees(&repos[idx].directory);
286	                stack.push(Screen::Sessions { repo_idx: idx, sel: 0, sessions, worktrees });
287	            }
288	            Cmd::Cd(path) => return Ok(Some(TuiOutcome::CdTo(path))),
289	            Cmd::ResumeSession(id, cwd) => return Ok(Some(TuiOutcome::ResumeSession { id, cwd })),
290	            Cmd::ShowSession(id) => {
291	                execute!(stdout, LeaveAlternateScreen, cursor::Show).ok();
292	                terminal::disable_raw_mode().ok();
293	                let quit_app = super::show::run(&id).unwrap_or(false);
294	                terminal::enable_raw_mode().ok();
295	                if quit_app { return Ok(Some(TuiOutcome::Quit)); }
296	                execute!(stdout, EnterAlternateScreen, cursor::Hide).ok();
297	                execute!(stdout, terminal::Clear(ClearType::All)).ok();
298	            }
299	            Cmd::Search(query) => {
300	                execute!(stdout, LeaveAlternateScreen, cursor::Show).ok();
301	                terminal::disable_raw_mode().ok();
302	                let quit_app = super::search::run(&query, 10, false).unwrap_or(false);
303	                terminal::enable_raw_mode().ok();
304	                if quit_app { return Ok(Some(TuiOutcome::Quit)); }
305	                execute!(stdout, EnterAlternateScreen, cursor::Hide).ok();
306	                execute!(stdout, terminal::Clear(ClearType::All)).ok();
307	            }
308	            Cmd::NewWorktree(branch) => {
309	                if let Some(Screen::Sessions { repo_idx, worktrees, .. }) = stack.last_mut() {
310	                    let repo_dir = &repos[*repo_idx].directory;
311	                    let notification = create_worktree(repo_dir, &branch);
312	                    // Refresh the worktree list whether or not it succeeded.
313	                    *worktrees = fetch_worktrees(repo_dir);
314	                    // Show the result in the status bar until the next keypress.
315	                    let (tw, th) = terminal::size().unwrap_or((120, 40));
316	                    let msg: String = notification.chars().take(tw as usize).collect();
317	                    let padded = format!("{:<width$}", msg, width = tw as usize);
318	                    execute!(stdout, cursor::MoveTo(0, th - 1)).ok();
319	                    write!(stdout, "\x1b[7m{padded}\x1b[0m").ok();
320	                    stdout.flush().ok();
321	                }
322	            }
323	            Cmd::NewSession(cfg) => {
324	                return Ok(Some(TuiOutcome::LaunchNewSession(cfg)));
325	            }
326	            Cmd::Tidy => {
327	                let repo_idx_opt = if let Some(Screen::Sessions { repo_idx, .. }) = stack.last() {
328	                    Some(*repo_idx)
329	                } else {
330	                    None
331	                };
332	                if let Some(repo_idx) = repo_idx_opt {
333	                    let repo = &repos[repo_idx];
334	                    let (tw, th) = terminal::size().unwrap_or((120, 40));
335	                    let changed = super::tidy::tui_tidy(
336	                        stdout,
337	                        std::slice::from_ref(repo),
338	                        7,
339	                        false,
340	                        tw as usize,
341	                        th as usize,
342	                    );
343	                    if changed {
344	                        if let Some(Screen::Sessions { worktrees, .. }) = stack.last_mut() {
345	                            *worktrees = fetch_worktrees(&repos[repo_idx].directory);
346	                        }
347	                    }
348	                    execute!(stdout, terminal::Clear(ClearType::All)).ok();
349	                }
350	            }
351	            Cmd::Redraw => { execute!(stdout, terminal::Clear(ClearType::All)).ok(); }
352	        }
353	    }
354	
355	    Ok(None)
356	}
