360	fn draw_repos(
361	    stdout: &mut impl Write,
362	    repos: &[Repository],
363	    sel: usize,
364	    current_repo_dir: Option<&str>,
365	    w: usize,
366	    h: usize,
367	    has_cd: bool,
368	) -> io::Result<()> {
369	    use crossterm::queue;
370	    let t = crate::theme::get();
371	    let content_h = h.saturating_sub(1);
372	    let mut buf: Vec<u8> = Vec::with_capacity((w + 40) * (h + 2));
373	    let mut row = 0usize;
374	
375	    let name_w = repos.iter().map(|r| r.name.chars().count()).max().unwrap_or(0);
376	    let dir_w  = repos.iter().map(|r| r.directory.chars().count()).max().unwrap_or(0);
377	
378	    for (i, repo) in repos.iter().enumerate() {
379	        if row >= content_h { break }
380	
381	        let is_sel = i == sel;
382	        let is_cur = current_repo_dir == Some(repo.directory.as_str());
383	        let dot_col = if is_cur { t.fresh } else { t.text_dim };
384	
385	        let name_padded = format!("{:<name_w$}", repo.name);
386	        let dir_padded  = format!("{:<dir_w$}",  repo.directory);
387	        let line = format!(
388	            "\x1b[{dot_col}m*\x1b[0m \x1b[{pm}m{name_padded}\x1b[0m  \x1b[{dm}m{dir_padded}  {}\x1b[0m",
389	            repo.remote, pm = t.text_primary, dm = t.text_dim,
390	        );
391	
392	        super::render_row(&mut buf, &line, is_sel, row, w)?;
393	        row += 1;
394	    }
395	
396	    while row < content_h {
397	        queue!(buf, cursor::MoveTo(0, row as u16), terminal::Clear(ClearType::UntilNewLine))?;
398	        row += 1;
399	    }
400	
401	    let cd_hint = if has_cd { "   c: cd" } else { "" };
402	    let bar = format!(
403	        "  {} repos   ↑↓/jk navigate   space: sessions   s: new session   /: search{}   q: quit  ",
404	        repos.len(), cd_hint
405	    );
406	    super::draw_statusbar(&mut buf, &bar, w, h)?;
407	
408	    stdout.write_all(&buf)?;
409	    stdout.flush()
410	}
