412	fn draw_sessions(
413	    stdout: &mut impl Write,
414	    repos: &[Repository],
415	    repo_idx: usize,
416	    sessions: &[RepoSession],
417	    worktrees: &[RepoWorktree],
418	    sel: usize,
419	    w: usize,
420	    h: usize,
421	) -> io::Result<()> {
422	    use crossterm::queue;
423	    let t = crate::theme::get();
424	    let content_h = h.saturating_sub(2); // header + status bar
425	    let mut buf: Vec<u8> = Vec::with_capacity((w + 40) * (h + 2));
426	
427	    // Header row
428	    queue!(buf, cursor::MoveTo(0, 0), terminal::Clear(ClearType::UntilNewLine))?;
429	    write!(buf, "\x1b[{hd}m{}\x1b[0m", repos[repo_idx].name, hd = t.header)?;
430	    let mut row = 1usize;
431	
432	    // ── Worktrees ────────────────────────────────────────────────────────────
433	    if !worktrees.is_empty() {
434	        for wt in worktrees.iter().take(content_h.saturating_sub(row + 1)) {
435	            if row >= content_h { break; }
436	
437	            let (branch_col, branch_label) = if wt.branch == "(detached)" {
438	                (t.error, format!("detached:{}", &wt.head))
439	            } else if wt.is_main {
440	                (t.accent, wt.branch.clone())
441	            } else {
442	                (t.link, wt.branch.clone())
443	            };
444	
445	            let path_short = super::short_path(&wt.path);
446	            let line = format!(
447	                "\x1b[{dm}m  @ \x1b[{branch_col}m{branch_label}\x1b[0m  \x1b[{dm}m{path_short}\x1b[0m",
448	                dm = t.text_dim,
449	            );
450	            queue!(buf, cursor::MoveTo(0, row as u16), terminal::Clear(ClearType::UntilNewLine))?;
451	            write!(buf, "{line}")?;
452	            row += 1;
453	        }
454	
455	        if row < content_h {
456	            queue!(buf, cursor::MoveTo(0, row as u16), terminal::Clear(ClearType::UntilNewLine))?;
457	            row += 1;
458	        }
459	    }
460	
461	    // ── Sessions ─────────────────────────────────────────────────────────────
462	    let sessions_start = row;
463	    let sessions_h = content_h.saturating_sub(sessions_start);
464	    let scroll = if sel >= sessions_h { sel + 1 - sessions_h } else { 0 };
465	
466	    if sessions.is_empty() {
467	        if row < content_h {
468	            queue!(buf, cursor::MoveTo(0, row as u16), terminal::Clear(ClearType::UntilNewLine))?;
469	            write!(buf, "\x1b[{dm}m  no sessions found\x1b[0m", dm = t.text_dim)?;
470	            row += 1;
471	        }
472	    } else {
473	        let name_w   = sessions.iter().map(|s| s.session_name.trim().chars().count()).max().unwrap_or(0).min(40);
474	        let branch_w = sessions.iter().map(|s| s.branch.chars().count()).max().unwrap_or(0);
475	        let author_w = sessions.iter().map(|s| s.author.chars().count()).max().unwrap_or(0);
476	        let agent_w  = sessions.iter().map(|s| s.agent_name.chars().count()).max().unwrap_or(0);
477	
478	        for (i, s) in sessions.iter().enumerate().skip(scroll) {
479	            if row >= content_h { break; }
480	
481	            let id_short: String = s.session_id.chars().take(8).collect();
482	            let ts = relative_time(s.updated_at);
483	            let clean = session_list::sanitize_one_line(&s.session_name);
484	            let name: String = clean.chars().take(name_w).collect();
485	            let age = (Utc::now() - s.updated_at).num_seconds().max(0);
486	            let dot_col = match age {
487	                a if a < 900   => t.fresh,
488	                a if a < 3_600 => t.moderate,
489	                _              => t.text_dim,
490	            };
491	
492	            let (meta_col, dot_char) = if s.backed_up {
493	                (t.backed_meta, "*")
494	            } else {
495	                (t.unbacked_meta, "·")
496	            };
497	            let name_col = if s.name_is_explicit {
498	                t.backed_name
499	            } else if s.backed_up {
500	                t.text_secondary
501	            } else {
502	                t.unbacked_name
503	            };
504	            let branch_col = if s.backed_up { t.link } else { t.stale };
505	
506	            let name_padded = format!("{:<name_w$}", name);
507	            let mut line = format!("\x1b[{dot_col}m{dot_char}\x1b[0m \x1b[{name_col}m{name_padded}\x1b[0m");
508	
509	            if branch_w > 0 {
510	                let b: String = s.branch.chars().take(branch_w).collect();
511	                let pad = " ".repeat(branch_w - b.chars().count());
512	                line.push_str(&format!("  \x1b[{branch_col}m{b}{pad}\x1b[0m"));
513	            }
514	
515	            if author_w > 0 {
516	                let a: String = s.author.chars().take(author_w).collect();
517	                let pad = " ".repeat(author_w - a.chars().count());
518	                line.push_str(&format!("  \x1b[{dm}m{a}{pad}\x1b[0m", dm = t.text_dim));
519	            }
520	
521	            if agent_w > 0 {
522	                let a: String = s.agent_name.chars().take(agent_w).collect();
523	                let pad = " ".repeat(agent_w - a.chars().count());
524	                if s.backed_up {
525	                    let col = agent_color(&s.agent_name);
526	                    line.push_str(&format!("  \x1b[38;5;{col}m{a}{pad}\x1b[0m"));
527	                } else {
528	                    line.push_str(&format!("  \x1b[{st}m{a}{pad}\x1b[0m", st = t.stale));
529	                }
530	            }
531	
532	            line.push_str(&format!("  \x1b[{meta_col}m{id_short}  {ts}\x1b[0m"));
533	
534	            super::render_row(&mut buf, &line, i == sel, row, w)?;
535	            row += 1;
536	        }
537	    }
538	
539	    while row < content_h {
540	        queue!(buf, cursor::MoveTo(0, row as u16), terminal::Clear(ClearType::UntilNewLine))?;
541	        row += 1;
542	    }
543	
544	    let bar = format!(
545	        "  {} sessions   ↑↓/jk navigate   space: view   r: resume   s: new session   n: new worktree   t: tidy   /: search   ←/h: back   q: quit  ",
546	        sessions.len()
547	    );
548	    super::draw_statusbar(&mut buf, &bar, w, h)?;
549	
550	    stdout.write_all(&buf)?;
551	    stdout.flush()
552	}
