554	// ── Worktree loading ──────────────────────────────────────────────────────────
555	
556	fn fetch_worktrees(repo_dir: &str) -> Vec<RepoWorktree> {
557	    let out = std::process::Command::new("git")
558	        .args(["worktree", "list", "--porcelain"])
559	        .current_dir(repo_dir)
560	        .output();
561	
562	    let Ok(out) = out else { return vec![]; };
563	    if !out.status.success() { return vec![]; }
564	    let text = String::from_utf8_lossy(&out.stdout);
565	
566	    let mut result = Vec::new();
567	    let mut first = true;
568	
569	    // Each worktree block is separated by a blank line.
570	    for block in text.split("\n\n") {
571	        let mut path = String::new();
572	        let mut head = String::new();
573	        let mut branch = String::new();
574	        let mut detached = false;
575	
576	        for line in block.lines() {
577	            if let Some(v) = line.strip_prefix("worktree ") {
578	                path = v.to_string();
579	            } else if let Some(v) = line.strip_prefix("HEAD ") {
580	                head = v.chars().take(8).collect();
581	            } else if let Some(v) = line.strip_prefix("branch refs/heads/") {
582	                branch = v.to_string();
583	            } else if line == "detached" {
584	                detached = true;
585	            }
586	        }
587	
588	        if path.is_empty() { continue; }
589	        if detached { branch = "(detached)".to_string(); }
590	        if branch.is_empty() { continue; } // bare worktree — skip
591	
592	        result.push(RepoWorktree { path, branch, head, is_main: first });
593	        first = false;
594	    }
595	
596	    result
597	}
