603	/// Generic single-line input shown in the status bar. Returns None on Esc.
604	pub(super) fn collect_text_input(stdout: &mut impl Write, prefix: &str, w: usize, h: usize) -> Option<String> {
605	    let mut value = String::new();
606	    execute!(stdout, cursor::Show).ok();
607	    draw_input_bar(stdout, prefix, &value, w, h).ok();
608	
609	    loop {
610	        match event::read().ok()? {
611	            Event::Key(k) => match k.code {
612	                KeyCode::Esc => {
613	                    execute!(stdout, cursor::Hide).ok();
614	                    return None;
615	                }
616	                KeyCode::Enter => {
617	                    execute!(stdout, cursor::Hide).ok();
618	                    return Some(value);
619	                }
620	                KeyCode::Backspace => {
621	                    value.pop();
622	                    draw_input_bar(stdout, prefix, &value, w, h).ok();
623	                }
624	                KeyCode::Char(c) => {
625	                    value.push(c);
626	                    draw_input_bar(stdout, prefix, &value, w, h).ok();
627	                }
628	                _ => {}
629	            },
630	            _ => {}
631	        }
632	    }
633	}
634	
635	fn draw_input_bar(stdout: &mut impl Write, prefix: &str, value: &str, w: usize, h: usize) -> io::Result<()> {
636	    let prefix_len = prefix.chars().count();
637	    let text: String = value.chars().take(w.saturating_sub(prefix_len + 2)).collect();
638	    let content = format!("{prefix}{text}");
639	    let padded = format!("{:<width$}", content, width = w);
640	    execute!(stdout, cursor::MoveTo(0, (h - 1) as u16))?;
641	    write!(stdout, "\x1b[7m{padded}\x1b[0m")?;
642	    let col = (prefix_len + text.chars().count()).min(w.saturating_sub(1)) as u16;
643	    execute!(stdout, cursor::MoveTo(col, (h - 1) as u16))?;
644	    stdout.flush()
645	}
