651	// ── New session wizard ────────────────────────────────────────────────────────
652	
653	/// A 4-step panel drawn over the bottom of the screen. Each completed step
654	/// stays visible with its confirmed value while the user fills the next one.
655	pub(super) fn new_session_wizard(stdout: &mut impl Write, repo_dir: &str, w: usize, h: usize) -> Option<NewSessionConfig> {
656	    const LABEL_W: usize = 24;
657	    // Panel rows: title, blank, agent, branch, name, prompt, blank  (7 rows + 1 status bar)
658	    const PANEL_H: usize = 7;
659	
660	    let t = crate::theme::get();
661	    let panel_top = h.saturating_sub(PANEL_H + 1);
662	
663	    let mut step = 0usize;           // 0=agent 1=branch 2=name 3=prompt
664	    let mut agent_sel = 0usize;
665	    let mut confirmed_agent = 0usize;
666	    let mut inputs = [String::new(), String::new(), String::new()]; // branch, name, prompt
667	
668	    execute!(stdout, cursor::Show).ok();
669	
670	    loop {
671	        // ── Draw panel ────────────────────────────────────────────────────────
672	        // Title row
673	        execute!(stdout, cursor::MoveTo(0, panel_top as u16)).ok();
674	        write!(stdout, "\x1b[{hd}m  New Session\x1b[0m", hd = t.header).ok();
675	        execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();
676	
677	        // Blank separator
678	        execute!(stdout, cursor::MoveTo(0, (panel_top + 1) as u16)).ok();
679	        execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();
680	
681	        let step_rows  = [panel_top + 2, panel_top + 3, panel_top + 4, panel_top + 5];
682	        let step_labels = ["  Agent", "  Worktree branch", "  Session name", "  Prompt"];
683	
684	        for (i, (&row, &label)) in step_rows.iter().zip(step_labels.iter()).enumerate() {
685	            execute!(stdout, cursor::MoveTo(0, row as u16)).ok();
686	            let lpart = format!("{label:<LABEL_W$}");
687	
688	            if i < step {
689	                // Completed — dim label, value in colour
690	                let val = if i == 0 {
691	                    let (name, _, col) = AGENTS[confirmed_agent];
692	                    format!("\x1b[38;5;{col}m{name}\x1b[0m")
693	                } else {
694	                    let v = inputs[i - 1].trim();
695	                    if v.is_empty() { format!("\x1b[{ft}m(skip)\x1b[0m", ft = t.text_faint) }
696	                    else            { format!("\x1b[{pm}m{v}\x1b[0m", pm = t.text_primary) }
697	                };
698	                write!(stdout, "\x1b[{dm}m{lpart}\x1b[0m{val}", dm = t.text_dim).ok();
699	            } else if i == step {
700	                // Active step
701	                write!(stdout, "\x1b[{pm}m{lpart}\x1b[0m", pm = t.text_primary).ok();
702	                if i == 0 {
703	                    // Inline agent picker
704	                    for (ai, (name, _, col)) in AGENTS.iter().enumerate() {
705	                        if ai > 0 { write!(stdout, "\x1b[{ft}m │ \x1b[0m", ft = t.text_faint).ok(); }
706	                        if ai == agent_sel {
707	                            write!(stdout, "\x1b[{sb};38;5;{col}m {name} \x1b[0m", sb = t.sel_bg).ok();
708	                        } else {
709	                            write!(stdout, "\x1b[{dm}m {name}\x1b[0m", dm = t.text_dim).ok();
710	                        }
711	                    }
712	                } else {
713	                    // Text input — print typed chars, terminal cursor sits here
714	                    write!(stdout, "\x1b[{pm}m{}\x1b[0m", inputs[i - 1], pm = t.text_primary).ok();
715	                }
716	            } else {
717	                // Future step — very dim label only
718	                write!(stdout, "\x1b[{ft}m{lpart}\x1b[0m", ft = t.text_faint).ok();
719	            }
720	            execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();
721	        }
722	
723	        // Trailing blank row
724	        let blank2 = panel_top + 6;
725	        if blank2 < h.saturating_sub(1) {
726	            execute!(stdout, cursor::MoveTo(0, blank2 as u16)).ok();
727	            execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();
728	        }
729	
730	        // Status bar hint
731	        let bar = if step == 0 {
732	            "  ↑↓/jk: select agent   enter: confirm   esc: cancel  "
733	        } else {
734	            "  type to enter   enter: next   esc: cancel  "
735	        };
736	        super::draw_statusbar(stdout, bar, w, h).ok();
737	
738	        // Position terminal cursor for text input steps
739	        if step > 0 {
740	            let row = step_rows[step];
741	            let col = (LABEL_W + inputs[step - 1].len()).min(w.saturating_sub(1));
742	            execute!(stdout, cursor::MoveTo(col as u16, row as u16)).ok();
743	        }
744	        stdout.flush().ok();
745	
746	        // ── Handle input ──────────────────────────────────────────────────────
747	        match event::read().ok()? {
748	            Event::Key(k) => match k.code {
749	                KeyCode::Esc => {
750	                    execute!(stdout, cursor::Hide).ok();
751	                    return None;
752	                }
753	                KeyCode::Up   | KeyCode::Char('k') if step == 0 => {
754	                    if agent_sel > 0 { agent_sel -= 1; }
755	                }
756	                KeyCode::Down | KeyCode::Char('j') if step == 0 => {
757	                    if agent_sel + 1 < AGENTS.len() { agent_sel += 1; }
758	                }
759	                KeyCode::Backspace if step > 0 => {
760	                    inputs[step - 1].pop();
761	                }
762	                KeyCode::Char(c) if step > 0 && !k.modifiers.contains(crossterm::event::KeyModifiers::CONTROL) => {
763	                    inputs[step - 1].push(c);
764	                }
765	                KeyCode::Enter => match step {
766	                    0 => { confirmed_agent = agent_sel; step = 1; }
767	                    1 | 2 => { step += 1; }
768	                    _ => {
769	                        execute!(stdout, cursor::Hide).ok();
770	                        let (agent_name, agent_cli, _) = AGENTS[confirmed_agent];
771	                        let branch_raw = inputs[0].trim().to_string();
772	                        return Some(NewSessionConfig {
773	                            agent_name: agent_name.to_string(),
774	                            agent_cli: agent_cli.to_string(),
775	                            branch: if branch_raw.is_empty() { None } else { Some(branch_raw) },
776	                            session_name: inputs[1].trim().to_string(),
777	                            prompt: inputs[2].trim().to_string(),
778	                            repo_dir: repo_dir.to_string(),
779	                        });
780	                    }
781	                },
782	                _ => {}
783	            },
784	            _ => {}
785	        }
786	    }
787	}
788	
789	// ── Helpers ───────────────────────────────────────────────────────────────────
790	
791	/// Create the worktree (if `cfg.branch` is set), copy the prompt to the
792	/// clipboard, then `exec` the agent. Only returns if `exec` failed.
793	pub(super) fn launch_new_session(cfg: NewSessionConfig) {
794	    use std::os::unix::process::CommandExt;
795	
796	    let launch_dir = if let Some(ref branch) = cfg.branch {
797	        let _ = create_worktree(&cfg.repo_dir, branch);
798	        let repo_path = std::path::Path::new(&cfg.repo_dir);
799	        let parent = repo_path.parent().unwrap_or(repo_path);
800	        let repo_name = repo_path.file_name()
801	            .map(|s| s.to_string_lossy().to_string())
802	            .unwrap_or_else(|| "repo".to_string());
803	        parent.join(format!("{repo_name}-{}", branch)).to_string_lossy().to_string()
804	    } else {
805	        cfg.repo_dir.clone()
806	    };
807	
808	    let prompt = cfg.prompt.trim().to_string();
809	    if !prompt.is_empty() {
810	        if let Ok(mut child) = std::process::Command::new("pbcopy")
811	            .stdin(std::process::Stdio::piped())
812	            .spawn()
813	        {
814	            if let Some(stdin) = child.stdin.as_mut() {
815	                let _ = stdin.write_all(prompt.as_bytes());
816	            }
817	            let _ = child.wait();
818	        }
819	    }
820	
821	    let session_name = cfg.session_name.trim().to_string();
822	    let mut cmd = std::process::Command::new(&cfg.agent_cli);
823	    if !launch_dir.is_empty() { cmd.current_dir(&launch_dir); }
824	    if !session_name.is_empty() { cmd.args(["-n", &session_name]); }
825	    if !prompt.is_empty() { cmd.arg(&prompt); }
826	    let err = cmd.exec();
827	    eprintln!("Failed to launch {}: {err}", cfg.agent_cli);
828	}
829	
830	pub(super) fn create_worktree(repo_dir: &str, branch: &str) -> String {
831	    let repo_path = std::path::Path::new(repo_dir);
832	    let parent = match repo_path.parent() {
833	        Some(p) => p,
834	        None => return "Error: cannot determine repo parent directory".to_string(),
835	    };
836	    let repo_name = repo_path
837	        .file_name()
838	        .map(|s| s.to_string_lossy().to_string())
839	        .unwrap_or_else(|| "repo".to_string());
840	    let wt_path = parent.join(format!("{repo_name}-{branch}"));
841	
842	    // Try -b (new branch) first; fall back to checking out an existing branch.
843	    let out = std::process::Command::new("git")
844	        .args(["worktree", "add", "-b", branch, wt_path.to_str().unwrap_or("")])
845	        .current_dir(repo_dir)
846	        .output();
847	
848	    match out {
849	        Err(e) => format!("Error: {e}"),
850	        Ok(o) if o.status.success() => {
851	            format!("Created worktree: {}", super::short_path(wt_path.to_str().unwrap_or("")))
852	        }
853	        Ok(o) => {
854	            let msg = String::from_utf8_lossy(&o.stderr);
855	            let first = msg.lines().find(|l| !l.trim().is_empty()).unwrap_or("unknown error");
856	            format!("Error: {first}")
857	        }
858	    }
859	}
860	
861	use super::agent_color;
862	
863	// Find which tracked repo the current directory belongs to — handles both the
864	// main worktree (starts_with match) and linked worktrees (git-common-dir match).
865	fn find_repo_for_cwd(repos: &[Repository]) -> Option<usize> {
866	    let cwd = env::current_dir().ok()?;
867	    let cwd_str = cwd.to_string_lossy();
868	
869	    // Main worktree: cwd is inside the repo root
870	    if let Some(idx) = repos.iter().position(|r| cwd_str.starts_with(r.directory.as_str())) {
871	        return Some(idx);
872	    }
873	
874	    // Linked worktree: git-common-dir points to the main repo's .git
875	    let out = std::process::Command::new("git")
876	        .args(["rev-parse", "--git-common-dir"])
877	        .current_dir(&cwd)
878	        .output()
879	        .ok()?;
880	    if !out.status.success() { return None; }
881	
882	    let common = String::from_utf8_lossy(&out.stdout).trim().to_string();
883	    let common_path = if std::path::Path::new(&common).is_absolute() {
884	        std::path::PathBuf::from(&common)
885	    } else {
886	        cwd.join(&common)
887	    };
888	
889	    // common_path is the .git dir; its parent is the repo root
890	    let repo_root = common_path.parent()?.to_string_lossy().to_string();
891	    repos.iter().position(|r| r.directory == repo_root)
892	}
893	
894	
895	fn relative_time(dt: DateTime<Utc>) -> String {
896	    let secs = (Utc::now() - dt).num_seconds().max(0);
897	    if secs < 604_800 {
898	        match secs {
899	            s if s < 60     => "just now".to_string(),
900	            s if s < 3_600  => format!("{} min{} ago", s/60,     if s/60==1     {""} else {"s"}),
901	            s if s < 86_400 => format!("{} hr{} ago",  s/3_600,  if s/3_600==1  {""} else {"s"}),
902	            s               => format!("{} day{} ago", s/86_400, if s/86_400==1 {""} else {"s"}),
903	        }
904	    } else {
905	        dt.with_timezone(&Local).format("%m/%d/%y").to_string()
906	    }
907	}
908	
909	pub fn run_for_dir(repo_dir: &str) -> Result<bool> {
910	    let conn = db::connect()?;
911	    let repos = fetch_repos(&conn)?;
912	    let start = repos.iter().position(|r| r.directory == repo_dir);
913	
914	    let orig_hook = std::panic::take_hook();
915	    std::panic::set_hook(Box::new(move |info| {
916	        let mut out = io::stdout();
917	        let _ = execute!(out, LeaveAlternateScreen, cursor::Show);
918	        let _ = terminal::disable_raw_mode();
919	        orig_hook(info);
920	    }));
921	
922	    let mut stdout = io::stdout();
923	    terminal::enable_raw_mode()?;
924	    execute!(stdout, EnterAlternateScreen, cursor::Hide)?;
925	
926	    let outcome = tui_loop(&mut stdout, &repos, false, start);
927	
928	    execute!(stdout, LeaveAlternateScreen, cursor::Show)?;
929	    terminal::disable_raw_mode()?;
930	
931	    let outcome = outcome?;
932	    let quit_app = matches!(outcome, Some(TuiOutcome::Quit));
933	    match outcome {
934	        Some(TuiOutcome::ResumeSession { id, cwd }) => {
935	            super::show::resume_session(&id, &cwd);
936	        }
937	        Some(TuiOutcome::LaunchNewSession(cfg)) => { launch_new_session(cfg); }
938	        _ => {}
939	    }
940	
941	    Ok(quit_app)
942	}
943	
944	pub fn fetch_repos(conn: &rusqlite::Connection) -> Result<Vec<Repository>> {
945	    let mut stmt = conn.prepare("SELECT id, directory, remote, name FROM repositories ORDER BY name")?;
946	    let repos = stmt.query_map([], |row| {
947	        Ok(Repository {
948	            id: row.get(0)?,
949	            directory: row.get(1)?,
950	            remote: row.get(2)?,
951	            name: row.get(3)?,
952	        })
953	    })?
954	    .collect::<Result<Vec<_>, _>>()?;
955	    Ok(repos)
956	}
