70	// ── Entry point ───────────────────────────────────────────────────────────────
71	
72	/// Returns `Ok(true)` if the user pressed `q` (or Ctrl+C) anywhere within the
73	/// search TUI or any nested viewer — parent TUI loops should propagate this
74	/// as a full-app exit. `Ok(false)` means a normal back-out (Esc).
75	pub fn run(query: &str, top_k: usize, json: bool) -> Result<bool> {
76	    let assets = crate::config::resolve_warp_assets()
77	        .ok_or_else(|| anyhow::anyhow!(
78	            "Witchcraft assets not configured.\nRun: gossamer config <path-to-witchcraft-assets>"
79	        ))?;
80	
81	    let db_path = dirs::home_dir()
82	        .ok_or_else(|| anyhow::anyhow!("cannot determine home directory"))?
83	        .join(".gossamer/search.db");
84	
85	    let db = witchcraft::DB::new_reader(db_path)
86	        .map_err(|e| anyhow::anyhow!("failed to open search DB: {e}"))?;
87	    let device = witchcraft::make_device();
88	    let embedder = witchcraft::Embedder::new(&device, &assets)
89	        .context("failed to load embedder")?;
90	    let mut cache = witchcraft::EmbeddingsCache::new(1);
91	
92	    const FLOOR:         f32 = 0.20;
93	    const LOG_THRESHOLD: f32 = 0.40;
94	    const SES_THRESHOLD: f32 = 0.25;
95	    const REP_THRESHOLD: f32 = 0.25;
96	
97	    let t0 = std::time::Instant::now();
98	    let raw = witchcraft::search(&db, &embedder, &mut cache, query, FLOOR, top_k * 4, true, None)?;
99	    let ms = t0.elapsed().as_millis();
100	
101	    let mut hits: Vec<SearchHit> = raw
102	        .iter()
103	        .filter_map(|(score, meta, bodies, sub_idx, _date)| {
104	            let hit = parse_hit(meta, bodies, *sub_idx as u32);
105	            let threshold = match hit.kind {
106	                HitKind::Log     => LOG_THRESHOLD,
107	                HitKind::Session => SES_THRESHOLD,
108	                HitKind::Repo    => REP_THRESHOLD,
109	            };
110	            if *score >= threshold { Some(hit) } else { None }
111	        })
112	        .take(top_k)
113	        .collect();
114	
115	    for hit in search_sessions_by_name(query) {
116	        let already = hits.iter().any(|h| {
117	            matches!(h.kind, HitKind::Session) && h.session_id == hit.session_id
118	        });
119	        if !already { hits.insert(0, hit); }
120	    }
121	    for hit in search_repos_by_name(query) {
122	        let already = hits.iter().any(|h| {
123	            matches!(h.kind, HitKind::Repo) && h.repo_dir == hit.repo_dir
124	        });
125	        if !already { hits.insert(0, hit); }
126	    }
127	    hits.truncate(top_k);
128	    enrich_hits(&mut hits);
129	
130	    let groups = build_groups(hits);
131	
132	    if json || !io::stdout().is_terminal() {
133	        let arr: Vec<serde_json::Value> = groups.iter().map(|g| {
134	            let hits_json: Vec<serde_json::Value> = g.rows.iter().map(|r| serde_json::json!({
135	                "timestamp": r.hit_ts,
136	                "excerpt": r.lines.join(" "),
137	            })).collect();
138	            serde_json::json!({
139	                "kind": g.kind.label(),
140	                "session_id": g.session_id,
141	                "session_name": g.title,
142	                "dir": g.dir,
143	                "branch": g.branch,
144	                "author": g.author,
145	                "agent": g.agent,
146	                "updated_at": g.updated_at,
147	                "backed_up": g.backed_up,
148	                "remote": g.remote,
149	                "hits": hits_json,
150	            })
151	        }).collect();
152	        println!("{}", serde_json::to_string_pretty(&serde_json::json!({
153	            "query": query,
154	            "results": arr,
155	        }))?);
156	        return Ok(false);
157	    }
158	
159	    let orig_hook = std::panic::take_hook();
160	    std::panic::set_hook(Box::new(move |info| {
161	        let mut out = io::stdout();
162	        let _ = execute!(out, LeaveAlternateScreen, cursor::Show);
163	        let _ = terminal::disable_raw_mode();
164	        orig_hook(info);
165	    }));
166	
167	    let mut stdout = io::stdout();
168	    terminal::enable_raw_mode()?;
169	    execute!(stdout, EnterAlternateScreen, cursor::Hide)?;
170	
171	    let result = tui_loop(&mut stdout, &groups, query, ms);
172	
173	    execute!(stdout, LeaveAlternateScreen, cursor::Show)?;
174	    terminal::disable_raw_mode()?;
175	
176	    result
177	}
