282	// ── Group building ────────────────────────────────────────────────────────────
283	
284	fn build_groups(hits: Vec<SearchHit>) -> Vec<Group> {
285	    let mut groups: Vec<Group> = Vec::new();
286	    let mut log_group_idx: std::collections::HashMap<String, usize> = std::collections::HashMap::new();
287	
288	    for hit in hits {
289	        match hit.kind {
290	            HitKind::Log => {
291	                let sid = hit.session_id.clone().unwrap_or_default();
292	                if let Some(&gi) = log_group_idx.get(&sid) {
293	                    groups[gi].rows.push(GroupRow {
294	                        hit_ts: hit.hit_ts,
295	                        start_ts: hit.start_ts,
296	                        lines: hit.excerpt_lines,
297	                    });
298	                } else {
299	                    let gi = groups.len();
300	                    if !sid.is_empty() { log_group_idx.insert(sid, gi); }
301	                    groups.push(Group {
302	                        title: hit.title,
303	                        dir: hit.dir,
304	                        branch: hit.branch,
305	                        agent: hit.agent,
306	                        backed_up: hit.backed_up,
307	                        updated_at: hit.updated_at,
308	                        remote: hit.remote,
309	                        session_id: hit.session_id,
310	                        repo_dir: None,
311	                        kind: HitKind::Log,
312	                        author: hit.author,
313	                        rows: vec![GroupRow {
314	                            hit_ts: hit.hit_ts,
315	                            start_ts: hit.start_ts,
316	                            lines: hit.excerpt_lines,
317	                        }],
318	                    });
319	                }
320	            }
321	            HitKind::Session => {
322	                groups.push(Group {
323	                    title: hit.title,
324	                    dir: hit.dir,
325	                    branch: String::new(),
326	                    agent: hit.agent,
327	                    backed_up: hit.backed_up,
328	                    updated_at: hit.updated_at,
329	                    remote: hit.remote,
330	                    session_id: hit.session_id,
331	                    repo_dir: None,
332	                    kind: HitKind::Session,
333	                    author: hit.author,
334	                    rows: vec![],
335	                });
336	            }
337	            HitKind::Repo => {
338	                groups.push(Group {
339	                    title: hit.title,
340	                    dir: hit.dir,
341	                    branch: String::new(),
342	                    agent: String::new(),
343	                    backed_up: false,
344	                    updated_at: String::new(),
345	                    remote: hit.remote,
346	                    session_id: None,
347	                    repo_dir: hit.repo_dir,
348	                    kind: HitKind::Repo,
349	                    author: String::new(),
350	                    rows: vec![],
351	                });
352	            }
353	        }
354	    }
355	
356	    groups
357	}
