439	// ── Rendering ─────────────────────────────────────────────────────────────────
440	
441	fn draw(
442	    stdout: &mut impl Write,
443	    groups: &[Group],
444	    query:  &str,
445	    ms:     u128,
446	    sel:    usize,
447	    scroll: usize,
448	    w:      usize,
449	    h:      usize,
450	) -> io::Result<()> {
451	    use crossterm::queue;
452	    let t = crate::theme::get();
453	    const TS_W: usize = 12; // fixed width of the timestamp column in excerpt rows
454	
455	    let content_h = h.saturating_sub(2);
456	    let mut buf: Vec<u8> = Vec::with_capacity((w + 60) * (h + 2));
457	
458	    // Title bar
459	    queue!(buf, cursor::MoveTo(0, 0), terminal::Clear(ClearType::UntilNewLine))?;
460	    let hdr = format!("  search: \"{}\"  {} result(s)  {}ms", query, groups.len(), ms);
461	    write!(buf, "\x1b[1m{}\x1b[0m", hdr.chars().take(w).collect::<String>())?;
462	
463	    // Pre-compute column widths across all groups for tabular alignment.
464	    let name_w   = groups.iter().map(|g| g.title.trim().chars().count()).max().unwrap_or(0).min(45);
465	    let agent_w  = groups.iter().map(|g| g.agent.chars().count()).max().unwrap_or(0);
466	    let author_w = groups.iter().map(|g| g.author.chars().count()).max().unwrap_or(0);
467	    let branch_w = groups.iter().map(|g| g.branch.chars().count()).max().unwrap_or(0).min(30);
468	
469	    let accent = t.accent;
470	    // Write one content line into the buffer using the ▌ bar for selection.
471	    let mut write_row = |buf: &mut Vec<u8>, line: &str, selected: bool, screen_row: usize| -> io::Result<()> {
472	        queue!(buf, cursor::MoveTo(0, screen_row as u16), terminal::Clear(ClearType::UntilNewLine))?;
473	        if selected {
474	            write!(buf, "\x1b[{accent}m▌\x1b[0m {line}")?;
475	        } else {
476	            write!(buf, "  {line}")?;
477	        }
478	        Ok(())
479	    };
480	
481	    let mut screen_row = 1usize; // next terminal row to write (row 0 is title bar)
482	    let mut abs_row    = 0usize; // absolute content row (before scroll is applied)
483	
484	    for (gi, group) in groups.iter().enumerate() {
485	        if screen_row > content_h { break; }
486	        let selected = gi == sel;
487	
488	        // ── Session header ────────────────────────────────────────────────
489	        if abs_row >= scroll && screen_row <= content_h {
490	            let age     = age_secs_hit(&group.updated_at);
491	            let dot_col = match age {
492	                a if a < 900   => t.fresh,
493	                a if a < 3_600 => t.moderate,
494	                _              => t.text_dim,
495	            };
496	            let (name_col, meta_col, dot_char) = if group.backed_up {
497	                (t.backed_name, t.backed_meta, "*")
498	            } else {
499	                (t.unbacked_name, t.unbacked_meta, "·")
500	            };
501	
502	            let name: String = group.title.trim().chars().take(name_w).collect();
503	            let name_padded  = format!("{name:<name_w$}");
504	            let mut line = format!(
505	                "\x1b[{dot_col}m{dot_char}\x1b[0m \x1b[{name_col}m{name_padded}\x1b[0m  \x1b[{dm}m{}\x1b[0m",
506	                group.dir, dm = t.text_dim,
507	            );
508	
509	            if branch_w > 0 {
510	                let branch_col = if group.backed_up { t.link } else { t.stale };
511	                let b: String = group.branch.chars().take(branch_w).collect();
512	                let pad = " ".repeat(branch_w - b.chars().count());
513	                line.push_str(&format!("  \x1b[{branch_col}m{b}{pad}\x1b[0m"));
514	            }
515	
516	            if author_w > 0 {
517	                let a: String = group.author.chars().take(author_w).collect();
518	                let pad = " ".repeat(author_w - a.chars().count());
519	                let col = super::author_color(&group.author);
520	                line.push_str(&format!("  \x1b[38;5;{col}m{a}\x1b[0m{pad}"));
521	            }
522	
523	            if agent_w > 0 {
524	                let a: String = group.agent.chars().take(agent_w).collect();
525	                let pad = " ".repeat(agent_w - a.chars().count());
526	                if group.backed_up {
527	                    let col = agent_color(&group.agent);
528	                    line.push_str(&format!("  \x1b[38;5;{col}m{a}{pad}\x1b[0m"));
529	                } else {
530	                    line.push_str(&format!("  \x1b[{st}m{a}{pad}\x1b[0m", st = t.stale));
531	                }
532	            }
533	
534	            if let Some(sid) = &group.session_id {
535	                let id_short: String = sid.chars().take(8).collect();
536	                let ts = rel_time_hit(&group.updated_at);
537	                line.push_str(&format!("  \x1b[{meta_col}m{id_short}  {ts}\x1b[0m"));
538	            } else if matches!(group.kind, HitKind::Repo) {
539	                line.push_str(&format!("  \x1b[{meta_col}mrepo\x1b[0m"));
540	            }
541	
542	            // Header row: full background highlight so the session name pops.
543	            super::render_row(&mut buf, &line, selected, screen_row, w)?;
544	            screen_row += 1;
545	        }
546	        abs_row += 1;
547	
548	        // ── Excerpt rows ──────────────────────────────────────────────────
549	        for row in &group.rows {
550	            let ts_str = row.hit_ts.as_deref().map(rel_time_hit).unwrap_or_default();
551	            let n_lines = row.lines.len().max(1);
552	            let excerpt_indent = " ".repeat(2 + TS_W + 2);
553	
554	            for li in 0..n_lines {
555	                if abs_row >= scroll && screen_row <= content_h {
556	                    let text = row.lines.get(li).map(String::as_str).unwrap_or("");
557	                    let avail = w.saturating_sub(2 + TS_W + 2);
558	                    let text_t: String = text.chars().take(avail).collect();
559	
560	                    let exc_line = if li == 0 {
561	                        let ts_padded = format!("{ts_str:>TS_W$}");
562	                        format!(
563	                            "  \x1b[{dm}m{ts_padded}\x1b[0m  \x1b[{sc}m{text_t}\x1b[0m",
564	                            dm = t.text_dim, sc = t.text_secondary,
565	                        )
566	                    } else {
567	                        format!("{excerpt_indent}\x1b[{sc}m{text_t}\x1b[0m", sc = t.text_secondary)
568	                    };
569	
570	                    // Excerpt rows: ▌ bar ties them visually to the selected header.
571	                    write_row(&mut buf, &exc_line, selected, screen_row)?;
572	                    screen_row += 1;
573	                }
574	                abs_row += 1;
575	            }
576	        }
577	
578	        // Blank separator row between groups
579	        if abs_row >= scroll && screen_row <= content_h {
580	            queue!(buf, cursor::MoveTo(0, screen_row as u16), terminal::Clear(ClearType::UntilNewLine))?;
581	            screen_row += 1;
582	        }
583	        abs_row += 1;
584	    }
585	
586	    // Clear any leftover rows below the results.
587	    while screen_row <= content_h {
588	        queue!(buf, cursor::MoveTo(0, screen_row as u16), terminal::Clear(ClearType::UntilNewLine))?;
589	        screen_row += 1;
590	    }
591	
592	    super::draw_statusbar(&mut buf, "  ↑↓/jk: navigate   space/→: open   q/esc: quit  ", w, h)?;
593	
594	    stdout.write_all(&buf)?;
595	    stdout.flush()
596	}
