599	// ── DB enrichment ─────────────────────────────────────────────────────────────
600	
601	fn enrich_hits(hits: &mut Vec<SearchHit>) {
602	    let Ok(conn) = crate::db::connect() else { return };
603	    for hit in hits.iter_mut() {
604	        if let Some(sid) = &hit.session_id {
605	            // Pull agent + remote, plus the first checkpoint's author (matching
606	            // the resolution session_list::query_db uses: name > email > os_user).
607	            if let Ok((agent, updated_at, remote, author_name, author_email, author_os_user)) =
608	                conn.query_row(
609	                    "SELECT s.agent_name, s.updated_at, COALESCE(r.remote, ''),
610	                            COALESCE(c.author_name, ''), COALESCE(c.author_email, ''),
611	                            COALESCE(c.os_user, '')
612	                     FROM sessions s
613	                     LEFT JOIN repositories r
614	                       ON (s.cwd = r.directory OR s.cwd LIKE r.directory || '/%')
615	                     LEFT JOIN checkpoints c
616	                       ON c.session_id = s.session_id
617	                      AND c.checkpoint_number = (
618	                            SELECT MIN(checkpoint_number) FROM checkpoints
619	                            WHERE session_id = s.session_id
620	                          )
621	                     WHERE s.session_id = ?1",
622	                    [sid.as_str()],
623	                    |row| Ok((
624	                        row.get::<_, String>(0)?,
625	                        row.get::<_, String>(1)?,
626	                        row.get::<_, String>(2)?,
627	                        row.get::<_, String>(3)?,
628	                        row.get::<_, String>(4)?,
629	                        row.get::<_, String>(5)?,
630	                    )),
631	                )
632	            {
633	                hit.agent      = agent;
634	                hit.updated_at = updated_at;
635	                hit.backed_up  = true;
636	                hit.remote     = remote;
637	                hit.author     = if !author_name.trim().is_empty() { author_name }
638	                                 else if !author_email.trim().is_empty() { author_email }
639	                                 else { author_os_user };
640	            }
641	        } else if let Some(dir) = &hit.repo_dir.clone() {
642	            if let Ok(remote) = conn.query_row(
643	                "SELECT COALESCE(remote, '') FROM repositories WHERE directory = ?1",
644	                [dir.as_str()],
645	                |row| row.get::<_, String>(0),
646	            ) {
647	                hit.remote = remote;
648	            }
649	        }
650	    }
651	}
652	
653	// ── Direct name search ────────────────────────────────────────────────────────
654	
655	fn search_sessions_by_name(query: &str) -> Vec<SearchHit> {
656	    let words: Vec<String> = query.split_whitespace().map(|w| w.to_lowercase()).collect();
657	    if words.is_empty() { return vec![]; }
658	
659	    let Ok(conn) = crate::db::connect() else { return vec![]; };
660	    let Ok(mut stmt) = conn.prepare(
661	        "SELECT session_id, session_name, cwd FROM sessions WHERE session_name != ''"
662	    ) else { return vec![]; };
663	
664	    stmt.query_map([], |row| Ok((row.get::<_,String>(0)?, row.get::<_,String>(1)?, row.get::<_,String>(2)?)))
665	        .ok()
666	        .into_iter()
667	        .flatten()
668	        .flatten()
669	        .filter_map(|(session_id, session_name, cwd): (String, String, String)| {
670	            let normalized = session_name.to_lowercase().replace(['-', '_'], " ");
671	            if words.iter().all(|w| normalized.contains(w.as_str())) {
672	                Some(SearchHit {
673	                    kind: HitKind::Session,
674	                    title: session_name,
675	                    dir: super::short_path(&cwd),
676	                    excerpt_lines: vec![],
677	                    session_id: Some(session_id),
678	                    repo_dir: None,
679	                    start_ts: None, hit_ts: None, branch: String::new(),
680	                    agent: String::new(), backed_up: false, updated_at: String::new(), author: String::new(),
681	                    remote: String::new(),
682	                })
683	            } else {
684	                None
685	            }
686	        })
687	        .collect()
688	}
689	
690	fn search_repos_by_name(query: &str) -> Vec<SearchHit> {
691	    let words: Vec<String> = query.split_whitespace().map(|w| w.to_lowercase()).collect();
692	    if words.is_empty() { return vec![]; }
693	
694	    let Ok(conn) = crate::db::connect() else { return vec![]; };
695	    let Ok(mut stmt) = conn.prepare(
696	        "SELECT name, directory, COALESCE(remote, '') FROM repositories WHERE name != ''"
697	    ) else { return vec![]; };
698	
699	    stmt.query_map([], |row| Ok((row.get::<_,String>(0)?, row.get::<_,String>(1)?, row.get::<_,String>(2)?)))
700	        .ok()
701	        .into_iter()
702	        .flatten()
703	        .flatten()
704	        .filter_map(|(name, directory, remote): (String, String, String)| {
705	            let normalized = name.to_lowercase().replace(['-', '_'], " ");
706	            if words.iter().all(|w| normalized.contains(w.as_str())) {
707	                Some(SearchHit {
708	                    kind: HitKind::Repo,
709	                    title: name,
710	                    dir: super::short_path(&directory),
711	                    excerpt_lines: vec![],
712	                    session_id: None,
713	                    repo_dir: Some(directory),
714	                    start_ts: None, hit_ts: None, branch: String::new(),
715	                    agent: String::new(), backed_up: false, updated_at: String::new(), author: String::new(),
716	                    remote,
717	                })
718	            } else {
719	                None
720	            }
721	        })
722	        .collect()
723	}
724	
725	// ── Helpers ───────────────────────────────────────────────────────────────────
726	
727	fn rel_time_hit(iso: &str) -> String {
728	    if iso.is_empty() { return String::new(); }
729	    let Ok(dt) = DateTime::parse_from_rfc3339(iso) else { return String::new(); };
730	    let secs = (Utc::now() - dt.with_timezone(&Utc)).num_seconds().max(0);
731	    if secs < 604_800 {
732	        match secs {
733	            s if s < 60     => "just now".into(),
734	            s if s < 3_600  => format!("{} min ago", s / 60),
735	            s if s < 86_400 => format!("{} hr ago",  s / 3_600),
736	            s               => format!("{} day{} ago", s / 86_400, if s / 86_400 == 1 { "" } else { "s" }),
737	        }
738	    } else {
739	        dt.with_timezone(&chrono::Local).format("%m/%d/%y").to_string()
740	    }
741	}
742	
743	fn age_secs_hit(iso: &str) -> i64 {
744	    if iso.is_empty() { return i64::MAX; }
745	    let Ok(dt) = DateTime::parse_from_rfc3339(iso) else { return i64::MAX; };
746	    (Utc::now() - dt.with_timezone(&Utc)).num_seconds().max(0)
747	}
748	
749	use super::agent_color;
750	
