use anyhow::{Context, Result};
use serde::Deserialize;
use std::cell::RefCell;
use std::collections::HashMap;
use std::process::Command;

use crate::{db, ingest};

pub(crate) const BRANCH: &str = "entire/checkpoints/v1";

/// Resolves a session's owning repository. Remote URL is the source of truth
/// — local paths are incidental to where someone happened to clone a repo.
/// Order of precedence:
///   1. **Mode B** (indexed repo's remote IS some tracked project's declared
///      `.entire/settings.json::checkpoint_remote`): pick the project that
///      uses this shared checkpoint repo; disambiguate by cwd if multiple.
///   2. **Mode A** (we have an indexing context but it isn't a shared
///      checkpoint repo): the file IS in this repo's checkpoint branch, so
///      by direct evidence it's this repo's session. The indexing context's
///      remote URL is authoritative — no need to consult the cwd.
///   3. **Backfill / no indexing context**: derive remote from cwd.
///      a. `git -C cwd remote get-url origin` matched against `repositories.remote`
///      b. cwd longest-prefix against tracked dirs (cross-machine fallback)
///      c. user-home-stripped suffix match (Scott's `/Users/sholodak/cosmos/X`
///         matches my `/Users/stsoucas/cosmos/X`)
///   4. Returns None if no signal at all.
///
/// Results of `git remote get-url origin` are cached so the cwd-derivation
/// path doesn't shell out repeatedly during a long index.
pub(crate) struct RepoResolver {
    repos: Vec<(i64, String, String)>,           // (id, directory, remote)
    by_remote: HashMap<String, i64>,             // normalized remote URL → repo_id
    project_for_checkpoint: HashMap<String, Vec<i64>>, // normalized cp-remote URL → project ids
    cwd_remote_cache: RefCell<HashMap<String, Option<String>>>,
}

impl RepoResolver {
    pub fn new(conn: &rusqlite::Connection) -> Result<Self> {
        let mut stmt = conn.prepare("SELECT id, directory, remote FROM repositories")?;
        let repos: Vec<(i64, String, String)> = stmt
            .query_map([], |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)))?
            .collect::<Result<_, _>>()?;

        let mut by_remote = HashMap::new();
        let mut project_for_checkpoint: HashMap<String, Vec<i64>> = HashMap::new();
        for (id, dir, remote) in &repos {
            if !remote.is_empty() {
                by_remote.insert(normalize_remote(remote), *id);
            }
            if let Some(cp_url) = checkpoint_remote_url(dir) {
                project_for_checkpoint.entry(normalize_remote(&cp_url))
                    .or_default()
                    .push(*id);
            }
        }

        Ok(Self {
            repos,
            by_remote,
            project_for_checkpoint,
            cwd_remote_cache: RefCell::new(HashMap::new()),
        })
    }

    pub fn resolve(&self, cwd: &str, indexing_context: Option<i64>) -> Option<i64> {
        // ── INDEXING CONTEXT (when we have one) ────────────────────────
        // We know the remote URL of the repo we're scanning — that IS the
        // session's remote URL, modulo the Mode B fan-out.
        if let Some(ctx_id) = indexing_context {
            if let Some(ctx_remote) = self.remote_of(ctx_id) {
                // 1. Mode B: ctx is a shared checkpoint repo. Disambiguate
                //    among the projects that use it as their checkpoint
                //    remote.
                if let Some(candidates) = self.project_for_checkpoint.get(&ctx_remote) {
                    if candidates.len() == 1 { return Some(candidates[0]); }
                    for &cand in candidates {
                        if let Some((_, dir, _)) = self.repos.iter().find(|(id, _, _)| *id == cand) {
                            if let Some(name) = std::path::Path::new(dir).file_name().and_then(|s| s.to_str()) {
                                if cwd.contains(name) { return Some(cand); }
                            }

use anyhow::Result;
use clap::{Parser, Subcommand};

mod commands;
mod config;
mod db;
mod entity;
mod ingest;
mod parsers;
mod theme;
mod watermark;

#[derive(Parser)]
#[command(name = "gossamer", about = "Manage AI sessions with entireio")]
struct Cli {
    #[command(subcommand)]
    command: Option<Commands>,

    /// Output as JSON instead of an interactive TUI
    #[arg(long, global = true)]
    json: bool,
}

#[derive(Subcommand)]
enum Commands {
    /// Initialize gossamer in the current git repository
    Init,
    /// Print all repositories tracked by gossamer
    Repo,
    /// Print sessions from the past 3 days
    Sessions {
        /// Show all sessions regardless of age
        #[arg(long)]
        all: bool,
    },
    /// Scan checkpoint logs and index sessions into the database
    Index,
    /// Incrementally index only new checkpoint commits since the last index/refresh
    Refresh,
    /// Browse a session's messages interactively (arrow keys to navigate)
    Show {
        /// Session ID or path to a JSONL file
        session: String,
    },
    /// Semantic search across indexed sessions
    Search {
        /// Search query (separate words are joined into one query)
        #[arg(required = true)]
        query: Vec<String>,
        /// Number of results to return
        #[arg(short = 'n', long, default_value = "10")]
        top_k: usize,
    },
    /// Start a new AI coding session, optionally in a fresh git worktree
    NewSession {
        /// Agent to use: claude, gemini, aider [default: claude]
        #[arg(long, short = 'a')]
        agent: Option<String>,
        /// Create a new git worktree on this branch before launching
        #[arg(long, short = 'b')]
        branch: Option<String>,
        /// Session name (passed as -n to the agent)
        #[arg(long, short = 'n')]
        name: Option<String>,
        /// Initial prompt, also copied to clipboard
        prompt: Option<String>,
    },
    /// Resume a session, checking out a new worktree if needed
    Resume {
        /// Session ID (full UUID or unambiguous prefix)
        session_id: String,
    },
    /// Remove a session: runs `entire clean`, deletes from DB, removes search index entries
    Clean {
        /// Session ID to clean up
        session_id: String,
    },
    /// Remove git worktrees that have had no recent session activity
    Tidy {
        /// Only list stale worktrees without removing them
        #[arg(long)]
        dry_run: bool,
        /// Days of inactivity before a worktree is considered stale
        #[arg(long, default_value = "7")]
        days: i64,
        /// Pass --force to git worktree remove (removes worktrees with uncommitted changes)
        #[arg(long)]
        force: bool,
        /// Also remove sessions whose cwd was inside each removed worktree
        #[arg(long)]
        sessions: bool,
    },
    /// Attach an existing session with entireio and index it into witchcraft
    Attach {
        /// Session ID to attach
        session_id: String,
        /// Agent name passed to `entire attach`
        #[arg(short, long, default_value = "claude-code")]
        agent: String,
        /// Pass --force to `entire attach`
        #[arg(short, long)]
        force: bool,
    },
    /// Show or set gossamer configuration
    Config {
        /// Path to the witchcraft assets directory (enables semantic search)
        assets: Option<String>,
    },
    /// Called by the Claude Code SessionStart hook — reads JSON from stdin
    #[command(hide = true)]
    SessionStart,
    /// Called by the Claude Code Stop hook — ingests the finished session
    #[command(hide = true)]
    SessionStop,
}

fn main() -> Result<()> {
    let cli = Cli::parse();
    let json = cli.json;
    // Detect the terminal theme before any command enables raw mode.
    // termbg queries the terminal via OSC 11, which requires non-raw mode.
    // Non-interactive contexts (pipes, hooks) skip this; termbg returns fast on no-tty.
    if !json && std::io::IsTerminal::is_terminal(&std::io::stdout()) {
        theme::get();
    }
    match cli.command.unwrap_or(Commands::Repo) {
        Commands::Init => commands::init::run(json)?,
        Commands::Repo => { commands::status::run(json)?; }
        Commands::Sessions { all } => { commands::sessions::run(all, json)?; }
        Commands::Index => commands::index::run(json)?,
        Commands::Refresh => commands::refresh::run(json)?,
        Commands::Show { session } => { commands::show::run(&session)?; }
        Commands::Search { query, top_k } => { commands::search::run(&query.join(" "), top_k, json)?; }
        Commands::NewSession { agent, branch, name, prompt } => {
            commands::new_session::run(agent, branch, name, prompt)?
        }
        Commands::Resume { session_id } => commands::resume::run(&session_id)?,
        Commands::Clean { session_id } => commands::clean::run(&session_id, json)?,
        Commands::Tidy { dry_run, days, force, sessions } => commands::tidy::run(days, dry_run, force, sessions, json)?,
        Commands::Attach { session_id, agent, force } => commands::attach::run(&session_id, &agent, force, json)?,
        Commands::Config { assets: Some(path) } => config::set_warp_assets(&path)?,
        Commands::Config { assets: None }       => config::show(),
        Commands::SessionStart => commands::session_start::run()?,
        Commands::SessionStop  => commands::session_stop::run()?,
    }
    Ok(())
}

