     fn xml_root_tag(text: &str) -> &str {
         let t = text.trim_start();
         let inner = t.strip_prefix('<').unwrap_or(t);
         let inner = inner.trim_start_matches(['!', '/']);
         let end = inner.find(|c: char| c == '>' || c == ' ' || c == '\n').unwrap_or(inner.len());
