use anyhow::Result;
use std::collections::HashSet;
use std::io::Write;
use std::path::PathBuf;
use std::process::Command;

use crate::db;

pub struct CandidateRepo {
    pub name:      String,
    pub directory: String,
    pub remote:    String,
}

// ── Scanning ──────────────────────────────────────────────────────────────────

/// Walk ~/.claude/projects JSONL files, extract every unique `cwd`, resolve
/// each to a git repo root with a GitHub remote, and return the ones not
/// already in `known_dirs`.
pub fn scan_candidates(known_dirs: &HashSet<String>) -> Vec<CandidateRepo> {
    let home = std::env::var("HOME").unwrap_or_default();
    let projects = PathBuf::from(&home).join(".claude/projects");

    let mut unique_cwds: HashSet<String> = HashSet::new();
    if let Ok(dirs) = std::fs::read_dir(&projects) {
        for dir in dirs.flatten() {
            if let Ok(files) = std::fs::read_dir(dir.path()) {
                for file in files.flatten() {
                    let path = file.path();
                    if path.extension().and_then(|e| e.to_str()) != Some("jsonl") { continue; }
                    if let Some(cwd) = extract_cwd(&path) { unique_cwds.insert(cwd); }
                }
            }
        }
    }

    let mut seen_roots: HashSet<String> = HashSet::new();
    let mut candidates: Vec<CandidateRepo> = Vec::new();

    for cwd in unique_cwds {
        if !std::path::Path::new(&cwd).is_dir() { continue; }

        let Ok(out) = Command::new("git")
            .args(["rev-parse", "--show-toplevel"])
            .current_dir(&cwd)
            .output()
        else { continue };
        if !out.status.success() { continue; }

        let root = String::from_utf8_lossy(&out.stdout).trim().to_string();
        if root.is_empty() || seen_roots.contains(&root) { continue; }
        seen_roots.insert(root.clone());
        if known_dirs.contains(&root) { continue; }

        let Ok(out) = Command::new("git")
            .args(["remote", "get-url", "origin"])
            .current_dir(&root)
            .output()
        else { continue };
        if !out.status.success() { continue; }

        let remote = String::from_utf8_lossy(&out.stdout).trim().to_string();
        if !remote.contains("github.com") { continue; }

        let name = repo_name_from_remote(&remote);
        candidates.push(CandidateRepo { name, directory: root, remote });
    }

    candidates.sort_by(|a, b| a.name.cmp(&b.name));
    candidates
}

fn extract_cwd(path: &std::path::Path) -> Option<String> {
    use std::io::BufRead;
    let file = std::fs::File::open(path).ok()?;
    for line in std::io::BufReader::new(file).lines().take(20).flatten() {
        if let Ok(v) = serde_json::from_str::<serde_json::Value>(&line) {
            if let Some(cwd) = v["cwd"].as_str() {
                if !cwd.is_empty() { return Some(cwd.to_string()); }
            }
        }
    }
    None
}

fn repo_name_from_remote(remote: &str) -> String {
    remote.rsplit('/').next().unwrap_or(remote)
        .trim_end_matches(".git")
        .to_string()
}

// ── Registration ──────────────────────────────────────────────────────────────

/// Insert candidates into the `repositories` table (idempotent) and backfill
/// local JSONL sessions whose cwd now resolves to one of the new repos.
/// Returns (repos_added, sessions_backfilled).
pub fn register_and_backfill(conn: &rusqlite::Connection, candidates: &[CandidateRepo]) -> Result<(usize, usize)> {
    let mut added = 0usize;
    for c in candidates {
        let rows = conn.execute(
            "INSERT OR IGNORE INTO repositories (directory, remote, name) VALUES (?1, ?2, ?3)",
            rusqlite::params![c.directory, c.remote, c.name],
        )?;
        added += rows;
    }

    let repos: Vec<(i64, String, String)> = {
        let mut stmt = conn.prepare("SELECT id, directory, remote FROM repositories")?;
        stmt.query_map([], |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)))?
            .collect::<Result<_, _>>()?
    };

    let resolver = crate::commands::index::RepoResolver::new(conn)?;
    let sessions = crate::commands::index::backfill_local_jsonls(conn, &repos, &resolver)?;
    Ok((added, sessions))
}

// ── CLI entry point ───────────────────────────────────────────────────────────

pub fn run(dry_run: bool, json: bool) -> Result<()> {
    let conn = db::connect()?;

    let known: HashSet<String> = {
        let mut stmt = conn.prepare("SELECT directory FROM repositories")?;
        stmt.query_map([], |row| row.get(0))?
            .collect::<Result<_, _>>()?
    };

    if !json { eprint!("Scanning…"); }
    let candidates = scan_candidates(&known);
    if !json { eprintln!(" done."); }

    if candidates.is_empty() {
        if json { println!("{}", serde_json::json!({"registered": [], "sessions_backfilled": 0})); }
        else     { println!("No new GitHub repositories found in your Claude session history."); }
        return Ok(());
    }

    if json {
        let arr: Vec<serde_json::Value> = candidates.iter().map(|c| serde_json::json!({
            "name": c.name, "directory": c.directory, "remote": c.remote,
        })).collect();
        if dry_run {
            println!("{}", serde_json::to_string_pretty(&serde_json::json!({"dry_run": true, "would_register": arr}))?);
        } else {
            let (added, sessions) = register_and_backfill(&conn, &candidates)?;
            println!("{}", serde_json::to_string_pretty(&serde_json::json!({
                "registered": arr, "repos_added": added, "sessions_backfilled": sessions,
            }))?);
        }
        return Ok(());
    }

    let t = crate::theme::get();
    println!("Found {} new GitHub repo{}:", candidates.len(), if candidates.len() == 1 { "" } else { "s" });
    for c in &candidates {
        let short = super::short_path(&c.directory);
        println!("  \x1b[1m{}\x1b[0m  \x1b[{dm}m{short}\x1b[0m", c.name, dm = t.text_dim);
    }

    if dry_run {
        println!("(dry run — nothing registered)");
        return Ok(());
    }

    let (added, sessions) = register_and_backfill(&conn, &candidates)?;
    println!("Registered {} repo(s), backfilled {} session(s).", added, sessions);
    Ok(())
}

// ── TUI overlay ───────────────────────────────────────────────────────────────

/// Interactive multi-select overlay. All candidates start checked. Returns
/// the selected subset, or `None` if the user cancelled.
pub(super) fn tui_discover(
    stdout: &mut impl Write,
    candidates: Vec<CandidateRepo>,
    w: usize,
    h: usize,
) -> Option<Vec<CandidateRepo>> {
    use crossterm::{cursor, event::{self, Event, KeyCode}, queue, terminal::{self, ClearType}};

    let mut selected: Vec<bool> = vec![true; candidates.len()];
    let mut sel = 0usize;
    let content_h = h.saturating_sub(2); // reserve title row + status bar

    let t = crate::theme::get();

    loop {
        let mut buf: Vec<u8> = Vec::with_capacity((w + 40) * (h + 2));

        // Title row
        queue!(buf, cursor::MoveTo(0, 0), terminal::Clear(ClearType::UntilNewLine)).ok();
        let n_sel: usize = selected.iter().filter(|&&s| s).count();
        write!(buf, "\x1b[{hd}m  Discovered repos\x1b[0m  \x1b[{dm}m{} found, {} selected\x1b[0m",
            candidates.len(), n_sel, hd = t.header, dm = t.text_dim).ok();

        // Candidate rows
        let scroll = if sel + 1 > content_h { sel + 1 - content_h } else { 0 };
        for (row, i) in (scroll..candidates.len()).take(content_h).enumerate() {
            let screen_row = (row + 1) as u16;
            queue!(buf, cursor::MoveTo(0, screen_row), terminal::Clear(ClearType::UntilNewLine)).ok();

            let c = &candidates[i];
            let check_col  = if selected[i] { t.fresh } else { t.text_faint };
            let check_char = if selected[i] { "x" } else { " " };
            let short = super::short_path(&c.directory);
            let remote_short: String = c.remote.chars().take(50).collect();

            let line = format!(
                "  \x1b[{check_col}m[{check_char}]\x1b[0m  \x1b[{pm}m{:<20}\x1b[0m  \x1b[{dm}m{:<35}  {remote_short}\x1b[0m",
                c.name, short, pm = t.text_primary, dm = t.text_dim,
            );

            if i == sel {
                let bg = t.sel_bg;
                let colored = super::with_bg(&line, bg);
                let vis = super::visible_width(&line);
                let pad = w.saturating_sub(vis);
                write!(buf, "\x1b[{bg}m{colored}{}\x1b[0m", " ".repeat(pad)).ok();
            } else {
                write!(buf, "{line}").ok();
            }
        }

        // Clear empty rows
        for row in (candidates.len() + 1)..=content_h {
            queue!(buf, cursor::MoveTo(0, row as u16), terminal::Clear(ClearType::UntilNewLine)).ok();
        }

        super::draw_statusbar(
            &mut buf,
            "  ↑↓/jk navigate   space: toggle   a: toggle all   enter: register selected   esc: cancel  ",
            w, h,
        ).ok();

        stdout.write_all(&buf).ok();
        stdout.flush().ok();

        match event::read().ok()? {
            Event::Key(k) => match k.code {
                KeyCode::Esc => return None,
                KeyCode::Enter => {
                    let result = candidates.into_iter()
                        .zip(selected)
                        .filter_map(|(c, s)| if s { Some(c) } else { None })
                        .collect();
                    return Some(result);
                }
                KeyCode::Up   | KeyCode::Char('k') => { if sel > 0 { sel -= 1; } }
                KeyCode::Down | KeyCode::Char('j') => { if sel + 1 < candidates.len() { sel += 1; } }
                KeyCode::Char(' ') => { selected[sel] = !selected[sel]; }
                KeyCode::Char('a') => {
                    let all = selected.iter().all(|&s| s);
                    selected.iter_mut().for_each(|s| *s = !all);
                }
                _ => {}
            },
            Event::Resize(nw, nh) => {
                let (w2, h2) = (nw as usize, nh as usize);
                // reborrow will use updated w/h on next iteration — but they're
                // captured by value, so just continue (slight sizing glitch ok here)
                let _ = (w2, h2);
            }
            _ => {}
        }
    }
}

use anyhow::Result;
use std::process::Command;

use crate::{db, ingest};
use witchcraft::types::{
    SqlConditionInternal, SqlOperator, SqlStatementInternal, SqlStatementType, SqlValue,
};

/// Resolve a session identifier (UUID or name) to the UUID used as the JSONL file stem.
/// Priority: exact session_id in DB → session_name in DB → customTitle scan of JSONL files → input as-is.
fn resolve_session_id(conn: &rusqlite::Connection, input: &str) -> String {
    if conn.query_row(
        "SELECT 1 FROM sessions WHERE session_id = ?1",
        rusqlite::params![input], |_| Ok(()),
    ).is_ok() {
        return input.to_string();
    }

    if let Ok(id) = conn.query_row(
        "SELECT session_id FROM sessions WHERE session_name = ?1 LIMIT 1",
        rusqlite::params![input], |row| row.get::<_, String>(0),
    ) {
        return id;
    }

    if let Some(id) = find_jsonl_by_title(input) {
        return id;
    }

    input.to_string()
}

fn find_jsonl_by_title(title: &str) -> Option<String> {
    let home = std::env::var("HOME").ok()?;
    let projects = std::path::PathBuf::from(&home).join(".claude/projects");
    for dir in std::fs::read_dir(&projects).ok()?.flatten() {
        for file in std::fs::read_dir(dir.path()).ok()?.flatten() {
            let path = file.path();
            if path.extension().and_then(|e| e.to_str()) != Some("jsonl") { continue; }
            let Ok(content) = std::fs::read_to_string(&path) else { continue };
            for line in content.lines() {
                let Ok(v) = serde_json::from_str::<serde_json::Value>(line) else { continue };
                if v["type"].as_str() == Some("custom-title")
                    && v["customTitle"].as_str() == Some(title)
                {
                    if let Some(stem) = path.file_stem().and_then(|s| s.to_str()) {
                        return Some(stem.to_string());
                    }
                }
            }
        }
    }
    None
}

/// Delete a session from the DB and search index without printing anything.
/// Runs `entire clean` silently. Returns the number of DB rows deleted.
/// Safe to call from inside a TUI (no stdout writes).
pub(crate) fn remove_session(session_id: &str) -> Result<usize> {
    let conn = db::connect()?;
    let rows = conn.execute(
        "DELETE FROM sessions WHERE session_id = ?1",
        rusqlite::params![session_id],
    )?;
    conn.execute("DELETE FROM event_log   WHERE session_id = ?1", rusqlite::params![session_id])?;
    conn.execute("DELETE FROM checkpoints WHERE session_id = ?1", rusqlite::params![session_id])?;

    if let Ok(mut wc_db) = ingest::open_search_db() {
        let filter = witchcraft::types::SqlStatementInternal {
            statement_type: witchcraft::types::SqlStatementType::Condition,
            condition: Some(witchcraft::types::SqlConditionInternal {
                key: "$.session_id".to_string(),
                operator: witchcraft::types::SqlOperator::Equals,
                value: Some(witchcraft::types::SqlValue::String(session_id.to_string())),
            }),
            logic: None,
            statements: None,
        };
        let _ = wc_db.delete_with_filter(&filter);
    }

    Ok(rows)
}

pub fn run(session_id_or_name: &str, json: bool) -> Result<()> {
    let conn = db::connect()?;
    let session_id = resolve_session_id(&conn, session_id_or_name);

    // entire clean — non-fatal (session may already be gone from entireio).
    match Command::new("entire").arg("clean").arg(&session_id).status() {
        Ok(s) if s.success() => {}
        Ok(s)  => eprintln!("warning: `entire clean` exited with {s}"),
        Err(e) => eprintln!("warning: could not run `entire clean`: {e}"),
    }

    let rows = conn.execute(
        "DELETE FROM sessions WHERE session_id = ?1",
        rusqlite::params![session_id],
    )?;
    conn.execute(
        "DELETE FROM event_log WHERE session_id = ?1",
        rusqlite::params![session_id],
    )?;

    if !json {
        if rows > 0 {
            println!("Removed '{}' from gossamer DB.", session_id);
        } else {
            println!("'{}' was not in gossamer DB.", session_id);
        }
    }

    let Ok(mut wc_db) = ingest::open_search_db() else {
        if json { println!("{}", serde_json::json!({"ok": true, "session_id": session_id, "db_rows_deleted": rows})); }
        return Ok(());
    };

    let filter = SqlStatementInternal {
        statement_type: SqlStatementType::Condition,
        condition: Some(SqlConditionInternal {
            key: "$.session_id".to_string(),
            operator: SqlOperator::Equals,
            value: Some(SqlValue::String(session_id.to_string())),
        }),
        logic: None,
        statements: None,
    };

    match wc_db.delete_with_filter(&filter) {
        Ok(_)  => { if !json { println!("Removed search index entries for '{}'.", session_id); } }
        Err(e) => eprintln!("Warning: could not clean search DB: {e}"),
    }

    if json {
        println!("{}", serde_json::to_string_pretty(&serde_json::json!({
            "ok": true,
            "session_id": session_id,
            "db_rows_deleted": rows,
        }))?);
    }

    Ok(())
}

use anyhow::Result;
use clap::{Parser, Subcommand};

mod commands;
mod config;
mod db;
mod entity;
mod ingest;
mod parsers;
mod theme;
mod watermark;

#[derive(Parser)]
#[command(name = "gossamer", about = "Manage AI sessions with entireio")]
struct Cli {
    #[command(subcommand)]
    command: Option<Commands>,

    /// Output as JSON instead of an interactive TUI
    #[arg(long, global = true)]
    json: bool,
}

#[derive(Subcommand)]
enum Commands {
    /// Initialize gossamer in the current git repository
    Init,
    /// Print all repositories tracked by gossamer
    Repo,
    /// Print sessions from the past 3 days
    Sessions {
        /// Show all sessions regardless of age
        #[arg(long)]
        all: bool,
    },
    /// Scan checkpoint logs and index sessions into the database
    Index,
    /// Incrementally index only new checkpoint commits since the last index/refresh
    Refresh,
    /// Browse a session's messages interactively (arrow keys to navigate)
    Show {
        /// Session ID or path to a JSONL file
        session: String,
    },
    /// Semantic search across indexed sessions
    Search {
        /// Search query (separate words are joined into one query)
        #[arg(required = true)]
        query: Vec<String>,
        /// Number of results to return
        #[arg(short = 'n', long, default_value = "10")]
        top_k: usize,
    },
    /// Start a new AI coding session, optionally in a fresh git worktree
    NewSession {
        /// Agent to use: claude, gemini, aider [default: claude]
        #[arg(long, short = 'a')]
        agent: Option<String>,
        /// Create a new git worktree on this branch before launching
        #[arg(long, short = 'b')]
        branch: Option<String>,
        /// Session name (passed as -n to the agent)
        #[arg(long, short = 'n')]
        name: Option<String>,
        /// Initial prompt, also copied to clipboard
        prompt: Option<String>,
    },
    /// Resume a session, checking out a new worktree if needed
    Resume {
        /// Session ID (full UUID or unambiguous prefix)
        session_id: String,
    },
    /// Remove a session: runs `entire clean`, deletes from DB, removes search index entries
    Clean {
        /// Session ID to clean up
        session_id: String,
    },
    /// Remove sessions from the DB that no longer exist in any checkpoint or Claude session file
    Purge {
        /// List stale sessions without deleting them
        #[arg(long)]
        dry_run: bool,
    },
    /// Remove git worktrees that have had no recent session activity
    Tidy {
        /// Only list stale worktrees without removing them
        #[arg(long)]
        dry_run: bool,
        /// Days of inactivity before a worktree is considered stale
        #[arg(long, default_value = "7")]
        days: i64,
        /// Pass --force to git worktree remove (removes worktrees with uncommitted changes)
        #[arg(long)]
        force: bool,
        /// Also remove sessions whose cwd was inside each removed worktree
        #[arg(long)]
        sessions: bool,
    },
    /// Attach an existing session with entireio and index it into witchcraft
    Attach {
        /// Session ID to attach
        session_id: String,
        /// Agent name passed to `entire attach`
        #[arg(short, long, default_value = "claude-code")]
        agent: String,
        /// Pass --force to `entire attach`
        #[arg(short, long)]
        force: bool,
    },
    /// Show or set gossamer configuration
    Config {
        /// Path to the witchcraft assets directory (enables semantic search)
        assets: Option<String>,
    },
    /// Called by the Claude Code SessionStart hook — reads JSON from stdin
    #[command(hide = true)]
    SessionStart,
    /// Called by the Claude Code Stop hook — ingests the finished session
    #[command(hide = true)]
    SessionStop,
}

fn main() -> Result<()> {
    let cli = Cli::parse();
    let json = cli.json;
    // Detect the terminal theme before any command enables raw mode.
    // termbg queries the terminal via OSC 11, which requires non-raw mode.
    // Non-interactive contexts (pipes, hooks) skip this; termbg returns fast on no-tty.
    if !json && std::io::IsTerminal::is_terminal(&std::io::stdout()) {
        theme::get();
    }
    match cli.command.unwrap_or(Commands::Repo) {
        Commands::Init => commands::init::run(json)?,
        Commands::Repo => { commands::status::run(json)?; }
        Commands::Sessions { all } => { commands::sessions::run(all, json)?; }
        Commands::Index => commands::index::run(json)?,
        Commands::Refresh => commands::refresh::run(json)?,
        Commands::Show { session } => { commands::show::run(&session)?; }
        Commands::Search { query, top_k } => { commands::search::run(&query.join(" "), top_k, json)?; }
        Commands::NewSession { agent, branch, name, prompt } => {
            commands::new_session::run(agent, branch, name, prompt)?
        }
        Commands::Resume { session_id } => commands::resume::run(&session_id)?,
        Commands::Clean { session_id } => commands::clean::run(&session_id, json)?,
        Commands::Purge { dry_run } => commands::purge::run(dry_run, json)?,
        Commands::Tidy { dry_run, days, force, sessions } => commands::tidy::run(days, dry_run, force, sessions, json)?,
        Commands::Attach { session_id, agent, force } => commands::attach::run(&session_id, &agent, force, json)?,
        Commands::Config { assets: Some(path) } => config::set_warp_assets(&path)?,
        Commands::Config { assets: None }       => config::show(),
        Commands::SessionStart => commands::session_start::run()?,
        Commands::SessionStop  => commands::session_stop::run()?,
    }
    Ok(())
}

