272	                        Some(b) if !b.trim().is_empty() => Cmd::NewWorktree(b.trim().to_string()),
273	                        _ => Cmd::Redraw,
274	                    },
275	                    KeyCode::Char('s') => {
276	                        let repo_dir = repos[*repo_idx].directory.clone();
277	                        match new_session_wizard(stdout, &repo_dir, w, h) {
278	                            Some(cfg) => Cmd::NewSession(cfg),
279	                            None => Cmd::Redraw,
280	                        }
281	                    }
282	                    KeyCode::Char('t') => Cmd::Tidy,
283	                    _ => { awaiting_delete = false; flash = None; Cmd::None }
284	                },
285	            },
286	            Event::Resize(_, _) => Cmd::Redraw,
287	            _ => Cmd::None,
288	        };
289	
290	        match cmd {
291	            Cmd::None => {}
292	            Cmd::Break => return Ok(Some(TuiOutcome::Quit)),
293	            Cmd::Back => {
294	                stack.pop();
295	                if stack.is_empty() { break; }
296	            }
297	            Cmd::PushSessions(idx) => {
298	                let sessions = session_list::fetch(Scope::Repo(&repos[idx]), true);
299	                let worktrees = fetch_worktrees(&repos[idx].directory);
300	                stack.push(Screen::Sessions { repo_idx: idx, sel: 0, sessions, worktrees });
301	            }
302	            Cmd::Cd(path) => return Ok(Some(TuiOutcome::CdTo(path))),
303	            Cmd::ResumeSession(id, cwd) => return Ok(Some(TuiOutcome::ResumeSession { id, cwd })),
304	            Cmd::DeleteSession(id) => {
305	                super::clean::remove_session(&id).ok();
306	                if let Some(Screen::Sessions { sel, sessions, .. }) = stack.last_mut() {
307	                    sessions.retain(|s| s.session_id != id);
308	                    if *sel >= sessions.len() && !sessions.is_empty() { *sel = sessions.len() - 1; }
309	                }
310	                execute!(stdout, terminal::Clear(ClearType::All)).ok();
311	            }
312	            Cmd::ShowSession(id) => {
313	                execute!(stdout, LeaveAlternateScreen, cursor::Show).ok();
314	                terminal::disable_raw_mode().ok();
315	                let quit_app = super::show::run(&id).unwrap_or(false);
316	                terminal::enable_raw_mode().ok();
317	                if quit_app { return Ok(Some(TuiOutcome::Quit)); }
318	                execute!(stdout, EnterAlternateScreen, cursor::Hide).ok();
319	                execute!(stdout, terminal::Clear(ClearType::All)).ok();
320	            }
321	            Cmd::Search(query) => {
322	                execute!(stdout, LeaveAlternateScreen, cursor::Show).ok();
323	                terminal::disable_raw_mode().ok();
324	                let quit_app = super::search::run(&query, 10, false).unwrap_or(false);
325	                terminal::enable_raw_mode().ok();
326	                if quit_app { return Ok(Some(TuiOutcome::Quit)); }
327	                execute!(stdout, EnterAlternateScreen, cursor::Hide).ok();
328	                execute!(stdout, terminal::Clear(ClearType::All)).ok();
329	            }
330	            Cmd::NewWorktree(branch) => {
331	                if let Some(Screen::Sessions { repo_idx, worktrees, .. }) = stack.last_mut() {
332	                    let repo_dir = &repos[*repo_idx].directory;
333	                    let notification = create_worktree(repo_dir, &branch);
334	                    // Refresh the worktree list whether or not it succeeded.
335	                    *worktrees = fetch_worktrees(repo_dir);
336	                    // Show the result in the status bar until the next keypress.
337	                    let (tw, th) = terminal::size().unwrap_or((120, 40));
338	                    let msg: String = notification.chars().take(tw as usize).collect();
339	                    let padded = format!("{:<width$}", msg, width = tw as usize);
340	                    execute!(stdout, cursor::MoveTo(0, th - 1)).ok();
341	                    write!(stdout, "\x1b[7m{padded}\x1b[0m").ok();
342	                    stdout.flush().ok();
343	                }
344	            }
345	            Cmd::NewSession(cfg) => {
346	                return Ok(Some(TuiOutcome::LaunchNewSession(cfg)));
347	            }
348	            Cmd::Tidy => {
349	                let repo_idx_opt = if let Some(Screen::Sessions { repo_idx, .. }) = stack.last() {
350	                    Some(*repo_idx)
351	                } else {
352	                    None
353	                };
354	                if let Some(repo_idx) = repo_idx_opt {
355	                    let repo = &repos[repo_idx];
356	                    let (tw, th) = terminal::size().unwrap_or((120, 40));
357	                    let changed = super::tidy::tui_tidy(
358	                        stdout,
359	                        std::slice::from_ref(repo),
360	                        7,
361	                        false,
362	                        tw as usize,
363	                        th as usize,
364	                    );
365	                    if changed {
366	                        if let Some(Screen::Sessions { worktrees, .. }) = stack.last_mut() {
367	                            *worktrees = fetch_worktrees(&repos[repo_idx].directory);
368	                        }
369	                    }
370	                    execute!(stdout, terminal::Clear(ClearType::All)).ok();
371	                }
372	            }
373	            Cmd::Redraw => { execute!(stdout, terminal::Clear(ClearType::All)).ok(); }
374	        }
375	    }
376	
377	    Ok(None)
378	}
