382	fn draw_repos(
383	    stdout: &mut impl Write,
384	    repos: &[Repository],
385	    sel: usize,
386	    current_repo_dir: Option<&str>,
387	    w: usize,
388	    h: usize,
389	    has_cd: bool,
390	) -> io::Result<()> {
391	    use crossterm::queue;
392	    let t = crate::theme::get();
393	    let content_h = h.saturating_sub(1);
394	    let mut buf: Vec<u8> = Vec::with_capacity((w + 40) * (h + 2));
395	    let mut row = 0usize;
396	
397	    let name_w = repos.iter().map(|r| r.name.chars().count()).max().unwrap_or(0);
398	    let dir_w  = repos.iter().map(|r| r.directory.chars().count()).max().unwrap_or(0);
399	
400	    for (i, repo) in repos.iter().enumerate() {
401	        if row >= content_h { break }
402	
403	        let is_sel = i == sel;
404	        let is_cur = current_repo_dir == Some(repo.directory.as_str());
405	        let dot_col = if is_cur { t.fresh } else { t.text_dim };
406	
407	        let name_padded = format!("{:<name_w$}", repo.name);
408	        let dir_padded  = format!("{:<dir_w$}",  repo.directory);
409	        let line = format!(
410	            "\x1b[{dot_col}m*\x1b[0m \x1b[{pm}m{name_padded}\x1b[0m  \x1b[{dm}m{dir_padded}  {}\x1b[0m",
411	            repo.remote, pm = t.text_primary, dm = t.text_dim,
412	        );
413	
414	        super::render_row(&mut buf, &line, is_sel, row, w)?;
415	        row += 1;
416	    }
417	
418	    while row < content_h {
419	        queue!(buf, cursor::MoveTo(0, row as u16), terminal::Clear(ClearType::UntilNewLine))?;
420	        row += 1;
421	    }
422	
423	    let cd_hint = if has_cd { "   c: cd" } else { "" };
424	    let bar = format!(
425	        "  {} repos   ↑↓/jk navigate   space: sessions   s: new session   / search{}   q: quit  ",
426	        repos.len(), cd_hint
427	    );
428	    super::draw_statusbar(&mut buf, &bar, w, h)?;
429	
430	    stdout.write_all(&buf)?;
431	    stdout.flush()
432	}
