434	fn draw_sessions(
435	    stdout: &mut impl Write,
436	    repos: &[Repository],
437	    repo_idx: usize,
438	    sessions: &[RepoSession],
439	    worktrees: &[RepoWorktree],
440	    sel: usize,
441	    w: usize,
442	    h: usize,
443	    flash: Option<&str>,
444	) -> io::Result<()> {
445	    use crossterm::queue;
446	    let t = crate::theme::get();
447	    let content_h = h.saturating_sub(2); // header + status bar
448	    let mut buf: Vec<u8> = Vec::with_capacity((w + 40) * (h + 2));
449	
450	    // Header row
451	    queue!(buf, cursor::MoveTo(0, 0), terminal::Clear(ClearType::UntilNewLine))?;
452	    write!(buf, "\x1b[{hd}m{}\x1b[0m", repos[repo_idx].name, hd = t.header)?;
453	    let mut row = 1usize;
454	
455	    // ── Worktrees ────────────────────────────────────────────────────────────
456	    if !worktrees.is_empty() {
457	        for wt in worktrees.iter().take(content_h.saturating_sub(row + 1)) {
458	            if row >= content_h { break; }
459	
460	            let (branch_col, branch_label) = if wt.branch == "(detached)" {
461	                (t.error, format!("detached:{}", &wt.head))
462	            } else if wt.is_main {
463	                (t.accent, wt.branch.clone())
464	            } else {
465	                (t.link, wt.branch.clone())
466	            };
467	
468	            let path_short = super::short_path(&wt.path);
469	            let line = format!(
470	                "\x1b[{dm}m  @ \x1b[{branch_col}m{branch_label}\x1b[0m  \x1b[{dm}m{path_short}\x1b[0m",
471	                dm = t.text_dim,
472	            );
473	            queue!(buf, cursor::MoveTo(0, row as u16), terminal::Clear(ClearType::UntilNewLine))?;
474	            write!(buf, "{line}")?;
475	            row += 1;
476	        }
477	
478	        if row < content_h {
479	            queue!(buf, cursor::MoveTo(0, row as u16), terminal::Clear(ClearType::UntilNewLine))?;
480	            row += 1;
481	        }
482	    }
483	
484	    // ── Sessions ─────────────────────────────────────────────────────────────
485	    let sessions_start = row;
486	    let sessions_h = content_h.saturating_sub(sessions_start);
487	    let scroll = if sel >= sessions_h { sel + 1 - sessions_h } else { 0 };
488	
489	    if sessions.is_empty() {
490	        if row < content_h {
491	            queue!(buf, cursor::MoveTo(0, row as u16), terminal::Clear(ClearType::UntilNewLine))?;
492	            write!(buf, "\x1b[{dm}m  no sessions found\x1b[0m", dm = t.text_dim)?;
493	            row += 1;
494	        }
495	    } else {
496	        let name_w   = sessions.iter().map(|s| s.session_name.trim().chars().count()).max().unwrap_or(0).min(40);
497	        let branch_w = sessions.iter().map(|s| s.branch.chars().count()).max().unwrap_or(0);
498	        let author_w = sessions.iter().map(|s| s.author.chars().count()).max().unwrap_or(0);
499	        let agent_w  = sessions.iter().map(|s| s.agent_name.chars().count()).max().unwrap_or(0);
500	
501	        for (i, s) in sessions.iter().enumerate().skip(scroll) {
502	            if row >= content_h { break; }
503	
504	            let id_short: String = s.session_id.chars().take(8).collect();
505	            let ts = relative_time(s.updated_at);
506	            let clean = session_list::sanitize_one_line(&s.session_name);
507	            let name: String = clean.chars().take(name_w).collect();
508	            let age = (Utc::now() - s.updated_at).num_seconds().max(0);
509	            let dot_col = match age {
510	                a if a < 900   => t.fresh,
511	                a if a < 3_600 => t.moderate,
512	                _              => t.text_dim,
513	            };
514	
515	            let (meta_col, dot_char) = if s.backed_up {
516	                (t.backed_meta, "*")
517	            } else {
518	                (t.unbacked_meta, "·")
519	            };
520	            let name_col = if s.name_is_explicit {
521	                t.backed_name
522	            } else if s.backed_up {
523	                t.text_secondary
524	            } else {
525	                t.unbacked_name
526	            };
527	            let branch_col = if s.backed_up { t.link } else { t.stale };
528	
529	            let name_padded = format!("{:<name_w$}", name);
530	            let mut line = format!("\x1b[{dot_col}m{dot_char}\x1b[0m \x1b[{name_col}m{name_padded}\x1b[0m");
531	
532	            if branch_w > 0 {
533	                let b: String = s.branch.chars().take(branch_w).collect();
534	                let pad = " ".repeat(branch_w - b.chars().count());
535	                line.push_str(&format!("  \x1b[{branch_col}m{b}{pad}\x1b[0m"));
536	            }
537	
538	            if author_w > 0 {
539	                let a: String = s.author.chars().take(author_w).collect();
540	                let pad = " ".repeat(author_w - a.chars().count());
541	                line.push_str(&format!("  \x1b[{dm}m{a}{pad}\x1b[0m", dm = t.text_dim));
542	            }
543	
544	            if agent_w > 0 {
545	                let a: String = s.agent_name.chars().take(agent_w).collect();
546	                let pad = " ".repeat(agent_w - a.chars().count());
547	                if s.backed_up {
548	                    let col = agent_color(&s.agent_name);
549	                    line.push_str(&format!("  \x1b[38;5;{col}m{a}{pad}\x1b[0m"));
550	                } else {
551	                    line.push_str(&format!("  \x1b[{st}m{a}{pad}\x1b[0m", st = t.stale));
552	                }
553	            }
554	
555	            line.push_str(&format!("  \x1b[{meta_col}m{id_short}  {ts}\x1b[0m"));
556	
557	            super::render_row(&mut buf, &line, i == sel, row, w)?;
558	            row += 1;
559	        }
560	    }
561	
562	    while row < content_h {
563	        queue!(buf, cursor::MoveTo(0, row as u16), terminal::Clear(ClearType::UntilNewLine))?;
564	        row += 1;
565	    }
566	
567	    let base = format!(
568	        "  {} sessions   ↑↓/jk navigate   space: view   r: resume   d: delete   s: new session   n: new worktree   t: tidy   / search   ←/h: back   q: quit  ",
569	        sessions.len()
570	    );
571	    let bar = if let Some(msg) = flash {
572	        let skip = msg.chars().count();
573	        let rest: String = base.chars().skip(skip).collect();
574	        format!("{msg}{rest}")
575	    } else { base };
576	    super::draw_statusbar(&mut buf, &bar, w, h)?;
577	
578	    stdout.write_all(&buf)?;
579	    stdout.flush()
580	}
