582	// ── Worktree loading ──────────────────────────────────────────────────────────
583	
584	fn fetch_worktrees(repo_dir: &str) -> Vec<RepoWorktree> {
585	    let out = std::process::Command::new("git")
586	        .args(["worktree", "list", "--porcelain"])
587	        .current_dir(repo_dir)
588	        .output();
589	
590	    let Ok(out) = out else { return vec![]; };
591	    if !out.status.success() { return vec![]; }
592	    let text = String::from_utf8_lossy(&out.stdout);
593	
594	    let mut result = Vec::new();
595	    let mut first = true;
596	
597	    // Each worktree block is separated by a blank line.
598	    for block in text.split("\n\n") {
599	        let mut path = String::new();
600	        let mut head = String::new();
601	        let mut branch = String::new();
602	        let mut detached = false;
603	
604	        for line in block.lines() {
605	            if let Some(v) = line.strip_prefix("worktree ") {
606	                path = v.to_string();
607	            } else if let Some(v) = line.strip_prefix("HEAD ") {
608	                head = v.chars().take(8).collect();
609	            } else if let Some(v) = line.strip_prefix("branch refs/heads/") {
610	                branch = v.to_string();
611	            } else if line == "detached" {
612	                detached = true;
613	            }
614	        }
615	
616	        if path.is_empty() { continue; }
617	        if detached { branch = "(detached)".to_string(); }
618	        if branch.is_empty() { continue; } // bare worktree — skip
619	
620	        result.push(RepoWorktree { path, branch, head, is_main: first });
621	        first = false;
622	    }
623	
624	    result
625	}
