633	/// A 4-step panel drawn over the bottom of the screen. Each completed step
634	/// stays visible with its confirmed value while the user fills the next one.
635	pub(super) fn new_session_wizard(stdout: &mut impl Write, repo_dir: &str, w: usize, h: usize) -> Option<NewSessionConfig> {
636	    const LABEL_W: usize = 24;
637	    // Panel rows: title, blank, agent, branch, name, prompt, blank  (7 rows + 1 status bar)
638	    const PANEL_H: usize = 7;
639	
640	    let t = crate::theme::get();
641	    let panel_top = h.saturating_sub(PANEL_H + 1);
642	
643	    let mut step = 0usize;           // 0=agent 1=branch 2=name 3=prompt
644	    let mut agent_sel = 0usize;
645	    let mut confirmed_agent = 0usize;
646	    let mut inputs = [String::new(), String::new(), String::new()]; // branch, name, prompt
647	
648	    execute!(stdout, cursor::Show).ok();
649	
650	    loop {
651	        // ── Draw panel ────────────────────────────────────────────────────────
652	        // Title row
653	        execute!(stdout, cursor::MoveTo(0, panel_top as u16)).ok();
654	        write!(stdout, "\x1b[{hd}m  New Session\x1b[0m", hd = t.header).ok();
655	        execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();
656	
657	        // Blank separator
658	        execute!(stdout, cursor::MoveTo(0, (panel_top + 1) as u16)).ok();
659	        execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();
660	
661	        let step_rows  = [panel_top + 2, panel_top + 3, panel_top + 4, panel_top + 5];
662	        let step_labels = ["  Agent", "  Worktree branch", "  Session name", "  Prompt"];
663	
664	        for (i, (&row, &label)) in step_rows.iter().zip(step_labels.iter()).enumerate() {
665	            execute!(stdout, cursor::MoveTo(0, row as u16)).ok();
666	            let lpart = format!("{label:<LABEL_W$}");
667	
668	            if i < step {
669	                // Completed — dim label, value in colour
670	                let val = if i == 0 {
671	                    let (name, _, col) = AGENTS[confirmed_agent];
672	                    format!("\x1b[38;5;{col}m{name}\x1b[0m")
673	                } else {
674	                    let v = inputs[i - 1].trim();
675	                    if v.is_empty() { format!("\x1b[{ft}m(skip)\x1b[0m", ft = t.text_faint) }
676	                    else            { format!("\x1b[{pm}m{v}\x1b[0m", pm = t.text_primary) }
677	                };
678	                write!(stdout, "\x1b[{dm}m{lpart}\x1b[0m{val}", dm = t.text_dim).ok();
679	            } else if i == step {
680	                // Active step
681	                write!(stdout, "\x1b[{pm}m{lpart}\x1b[0m", pm = t.text_primary).ok();
682	                if i == 0 {
683	                    // Inline agent picker
684	                    for (ai, (name, _, col)) in AGENTS.iter().enumerate() {
685	                        if ai > 0 { write!(stdout, "\x1b[{ft}m │ \x1b[0m", ft = t.text_faint).ok(); }
686	                        if ai == agent_sel {
687	                            write!(stdout, "\x1b[{sb};38;5;{col}m {name} \x1b[0m", sb = t.sel_bg).ok();
688	                        } else {
689	                            write!(stdout, "\x1b[{dm}m {name}\x1b[0m", dm = t.text_dim).ok();
690	                        }
691	                    }
692	                } else {
693	                    // Text input — print typed chars, terminal cursor sits here
694	                    write!(stdout, "\x1b[{pm}m{}\x1b[0m", inputs[i - 1], pm = t.text_primary).ok();
695	                }
696	            } else {
697	                // Future step — very dim label only
698	                write!(stdout, "\x1b[{ft}m{lpart}\x1b[0m", ft = t.text_faint).ok();
699	            }
700	            execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();
701	        }
702	
703	        // Trailing blank row
704	        let blank2 = panel_top + 6;
705	        if blank2 < h.saturating_sub(1) {
706	            execute!(stdout, cursor::MoveTo(0, blank2 as u16)).ok();
707	            execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();
708	        }
709	
710	        // Status bar hint
711	        let bar = if step == 0 {
712	            "  ↑↓/jk: select agent   enter: confirm   esc: cancel  "
713	        } else {
714	            "  type to enter   enter: next   esc: cancel  "
715	        };
716	        super::draw_statusbar(stdout, bar, w, h).ok();
717	
718	        // Position terminal cursor for text input steps
719	        if step > 0 {
720	            let row = step_rows[step];
721	            let col = (LABEL_W + inputs[step - 1].len()).min(w.saturating_sub(1));
722	            execute!(stdout, cursor::MoveTo(col as u16, row as u16)).ok();
723	        }
724	        stdout.flush().ok();
725	
726	        // ── Handle input ──────────────────────────────────────────────────────
727	        match event::read().ok()? {
728	            Event::Key(k) => match k.code {
729	                KeyCode::Esc => {
730	                    execute!(stdout, cursor::Hide).ok();
731	                    return None;
732	                }
733	                KeyCode::Up   | KeyCode::Char('k') if step == 0 => {
734	                    if agent_sel > 0 { agent_sel -= 1; }
735	                }
736	                KeyCode::Down | KeyCode::Char('j') if step == 0 => {
737	                    if agent_sel + 1 < AGENTS.len() { agent_sel += 1; }
738	                }
739	                KeyCode::Backspace if step > 0 => {
740	                    inputs[step - 1].pop();
741	                }
742	                KeyCode::Char(c) if step > 0 && !k.modifiers.contains(crossterm::event::KeyModifiers::CONTROL) => {
743	                    inputs[step - 1].push(c);
744	                }
745	                KeyCode::Enter => match step {
746	                    0 => { confirmed_agent = agent_sel; step = 1; }
747	                    1 | 2 => { step += 1; }
748	                    _ => {
749	                        execute!(stdout, cursor::Hide).ok();
750	                        let (agent_name, agent_cli, _) = AGENTS[confirmed_agent];
751	                        let branch_raw = inputs[0].trim().to_string();
752	                        return Some(NewSessionConfig {
753	                            agent_name: agent_name.to_string(),
754	                            agent_cli: agent_cli.to_string(),
755	                            branch: if branch_raw.is_empty() { None } else { Some(branch_raw) },
756	                            session_name: inputs[1].trim().to_string(),
757	                            prompt: inputs[2].trim().to_string(),
758	                            repo_dir: repo_dir.to_string(),
759	                        });
760	                    }
761	                },
762	                _ => {}
763	            },
764	            _ => {}
765	        }
766	    }
767	}
