770	
771	/// Create the worktree (if `cfg.branch` is set), copy the prompt to the
772	/// clipboard, then `exec` the agent. Only returns if `exec` failed.
773	pub(super) fn launch_new_session(cfg: NewSessionConfig) {
774	    use std::os::unix::process::CommandExt;
775	
776	    let launch_dir = if let Some(ref branch) = cfg.branch {
777	        let _ = create_worktree(&cfg.repo_dir, branch);
778	        let repo_path = std::path::Path::new(&cfg.repo_dir);
779	        let parent = repo_path.parent().unwrap_or(repo_path);
780	        let repo_name = repo_path.file_name()
781	            .map(|s| s.to_string_lossy().to_string())
782	            .unwrap_or_else(|| "repo".to_string());
783	        parent.join(format!("{repo_name}-{}", branch)).to_string_lossy().to_string()
784	    } else {
785	        cfg.repo_dir.clone()
786	    };
787	
788	    let prompt = cfg.prompt.trim().to_string();
789	    if !prompt.is_empty() {
790	        if let Ok(mut child) = std::process::Command::new("pbcopy")
791	            .stdin(std::process::Stdio::piped())
792	            .spawn()
793	        {
794	            if let Some(stdin) = child.stdin.as_mut() {
795	                let _ = stdin.write_all(prompt.as_bytes());
796	            }
797	            let _ = child.wait();
798	        }
799	    }
800	
801	    let session_name = cfg.session_name.trim().to_string();
802	    let mut cmd = std::process::Command::new(&cfg.agent_cli);
803	    if !launch_dir.is_empty() { cmd.current_dir(&launch_dir); }
804	    if !session_name.is_empty() { cmd.args(["-n", &session_name]); }
805	    if !prompt.is_empty() { cmd.arg(&prompt); }
806	    let err = cmd.exec();
807	    eprintln!("Failed to launch {}: {err}", cfg.agent_cli);
808	}
809	
810	pub(super) fn create_worktree(repo_dir: &str, branch: &str) -> String {
811	    let repo_path = std::path::Path::new(repo_dir);
812	    let parent = match repo_path.parent() {
813	        Some(p) => p,
814	        None => return "Error: cannot determine repo parent directory".to_string(),
815	    };
816	    let repo_name = repo_path
817	        .file_name()
818	        .map(|s| s.to_string_lossy().to_string())
819	        .unwrap_or_else(|| "repo".to_string());
820	    let wt_path = parent.join(format!("{repo_name}-{branch}"));
821	
822	    // Try -b (new branch) first; fall back to checking out an existing branch.
823	    let out = std::process::Command::new("git")
824	        .args(["worktree", "add", "-b", branch, wt_path.to_str().unwrap_or("")])
825	        .current_dir(repo_dir)
826	        .output();
827	
828	    match out {
829	        Err(e) => format!("Error: {e}"),
830	        Ok(o) if o.status.success() => {
831	            format!("Created worktree: {}", super::short_path(wt_path.to_str().unwrap_or("")))
832	        }
833	        Ok(o) => {
834	            let msg = String::from_utf8_lossy(&o.stderr);
835	            let first = msg.lines().find(|l| !l.trim().is_empty()).unwrap_or("unknown error");
836	            format!("Error: {first}")
837	        }
838	    }
839	}
840	
841	use super::agent_color;
842	
843	// Find which tracked repo the current directory belongs to — handles both the
844	// main worktree (starts_with match) and linked worktrees (git-common-dir match).
845	fn find_repo_for_cwd(repos: &[Repository]) -> Option<usize> {
846	    let cwd = env::current_dir().ok()?;
847	    let cwd_str = cwd.to_string_lossy();
848	
849	    // Main worktree: cwd is inside the repo root
850	    if let Some(idx) = repos.iter().position(|r| cwd_str.starts_with(r.directory.as_str())) {
851	        return Some(idx);
852	    }
853	
854	    // Linked worktree: git-common-dir points to the main repo's .git
855	    let out = std::process::Command::new("git")
856	        .args(["rev-parse", "--git-common-dir"])
857	        .current_dir(&cwd)
858	        .output()
859	        .ok()?;
860	    if !out.status.success() { return None; }
861	
862	    let common = String::from_utf8_lossy(&out.stdout).trim().to_string();
863	    let common_path = if std::path::Path::new(&common).is_absolute() {
864	        std::path::PathBuf::from(&common)
865	    } else {
866	        cwd.join(&common)
867	    };
868	
869	    // common_path is the .git dir; its parent is the repo root
870	    let repo_root = common_path.parent()?.to_string_lossy().to_string();
871	    repos.iter().position(|r| r.directory == repo_root)
872	}
