875	fn relative_time(dt: DateTime<Utc>) -> String {
876	    let secs = (Utc::now() - dt).num_seconds().max(0);
877	    if secs < 604_800 {
878	        match secs {
879	            s if s < 60     => "just now".to_string(),
880	            s if s < 3_600  => format!("{} min{} ago", s/60,     if s/60==1     {""} else {"s"}),
881	            s if s < 86_400 => format!("{} hr{} ago",  s/3_600,  if s/3_600==1  {""} else {"s"}),
882	            s               => format!("{} day{} ago", s/86_400, if s/86_400==1 {""} else {"s"}),
883	        }
884	    } else {
885	        dt.with_timezone(&Local).format("%m/%d/%y").to_string()
886	    }
887	}
