890	    let conn = db::connect()?;
891	    let repos = fetch_repos(&conn)?;
892	    let start = repos.iter().position(|r| r.directory == repo_dir);
893	
894	    let orig_hook = std::panic::take_hook();
895	    std::panic::set_hook(Box::new(move |info| {
896	        let mut out = io::stdout();
897	        let _ = execute!(out, LeaveAlternateScreen, cursor::Show);
898	        let _ = terminal::disable_raw_mode();
899	        orig_hook(info);
900	    }));
901	
902	    let mut stdout = io::stdout();
903	    terminal::enable_raw_mode()?;
904	    execute!(stdout, EnterAlternateScreen, cursor::Hide)?;
905	
906	    let outcome = tui_loop(&mut stdout, &repos, false, start);
907	
908	    execute!(stdout, LeaveAlternateScreen, cursor::Show)?;
909	    terminal::disable_raw_mode()?;
910	
911	    let outcome = outcome?;
912	    let quit_app = matches!(outcome, Some(TuiOutcome::Quit));
913	    match outcome {
914	        Some(TuiOutcome::ResumeSession { id, cwd }) => {
915	            super::show::resume_session(&id, &cwd);
916	        }
917	        Some(TuiOutcome::LaunchNewSession(cfg)) => { launch_new_session(cfg); }
918	        _ => {}
919	    }
920	
921	    Ok(quit_app)
922	}
923	
924	pub fn fetch_repos(conn: &rusqlite::Connection) -> Result<Vec<Repository>> {
925	    let mut stmt = conn.prepare("SELECT id, directory, remote, name FROM repositories ORDER BY name")?;
926	    let repos = stmt.query_map([], |row| {
927	        Ok(Repository {
928	            id: row.get(0)?,
929	            directory: row.get(1)?,
930	            remote: row.get(2)?,
931	            name: row.get(3)?,
932	        })
933	    })?
934	    .collect::<Result<Vec<_>, _>>()?;
935	    Ok(repos)
