37	/// Visible character width of an ANSI-escaped string (skips escape sequences).
38	pub(super) fn visible_width(s: &str) -> usize {
39	    let mut w = 0usize;
40	    let mut chars = s.chars().peekable();
41	    while let Some(c) = chars.next() {
42	        if c == '\x1b' {
43	            for nc in chars.by_ref() { if nc.is_ascii_alphabetic() { break; } }
44	        } else {
45	            w += 1;
46	        }
47	    }
48	    w
49	}
